import type { BankQuestion } from "@/lib/bank";

/** Grammar and Error Spotting (English): 375 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"eng-grammar-1","question":"He has been working here ___ 2015.","options":["for","since","from","until"],"answer":1,"explanation":"'Since' marks the starting point of an action that continues to now, as the present perfect continuous here demands. 'For' needs a length of time ('for ten years'), and 'from' needs an end point ('from 2015 to 2020').","difficulty":"easy"},
  {"id":"eng-grammar-2","question":"She ___ to school every day.","options":["go","goes","going","gone"],"answer":1,"explanation":"With a third-person singular subject ('she') the simple present adds -s/-es: 'goes'. 'Going' and 'gone' are participles and need a helping verb such as 'is' or 'has'.","difficulty":"easy"},
  {"id":"eng-grammar-3","question":"He is ___ honest man.","options":["a","an","the","no article"],"answer":1,"explanation":"“Honest” begins with a vowel sound (the h is silent), so it takes “an”.","difficulty":"easy"},
  {"id":"eng-grammar-4","question":"Neither of the boys ___ present.","options":["were","are","was","have been"],"answer":2,"explanation":"'Neither of' + plural noun takes the boys one at a time, so formal English uses a singular verb: 'was'. The plural 'were' is the usual trap, pulled by the nearby word 'boys'.","difficulty":"moderate"},
  {"id":"eng-grammar-5","question":"One of my friends ___ a doctor.","options":["are","is","were","have"],"answer":1,"explanation":"The subject is 'one', not 'friends', so the verb is singular: 'is'. 'Of my friends' only names the group the one comes from, so 'are' agrees with the wrong word.","difficulty":"moderate"},
  {"id":"eng-grammar-6","question":"The news ___ very shocking.","options":["are","were","is","have been"],"answer":2,"explanation":"'News' looks plural but is an uncountable noun, so it takes a singular verb: 'is'. The final -s misleads many into choosing 'are' or 'have been'.","difficulty":"moderate"},
  {"id":"eng-grammar-7","question":"Choose the correctly spelt word.","options":["Acommodate","Accomodate","Accommodate","Accommmodate"],"answer":2,"explanation":"Accommodate has a double c and a double m (ac-com-mo-date). The commonest misspelling drops one m, as in 'Accomodate'; tripling the m is the over-correction.","difficulty":"hard"},
  {"id":"eng-grammar-8","question":"Each of the students ___ given a prize.","options":["were","was","have","are"],"answer":1,"explanation":"'Each of' is singular, since it picks out the students one by one, so the verb is 'was' (given). The plural noun 'students' is the trap that pulls towards 'were'.","difficulty":"hard"},
  {"id":"eng-grammar-9","question":"Spot the error: “He is senior than me in the office.”","options":["He is","senior than","me in","the office"],"answer":1,"explanation":"Senior, junior, superior and inferior take “to”, not “than”: senior to me.","difficulty":"hard"},
  {"id":"eng-grammar-10","question":"Choose the correct sentence.","options":["I have seen him yesterday.","I saw him yesterday.","I had seen him yesterday.","I have been seeing him yesterday."],"answer":1,"explanation":"A definite past time (“yesterday”) takes the simple past, not the present perfect.","difficulty":"very-hard"},
  {"id":"eng-grammar-11","question":"Hardly had he left the house ___ it started raining.","options":["than","when","then","that"],"answer":1,"explanation":"“Hardly … when” and “No sooner … than” are the correct pairs.","difficulty":"very-hard"},
  {"id":"eng-grammar-12","question":"Which of the following words is spelt correctly?","options":["Occurence","Occurrence","Ocurrence","Occurrance"],"answer":1,"explanation":"Occurrence doubles both the c and the r (oc-cur-rence) and ends in -ence, not -ance. 'Occurence', with a single r, is the most frequent slip.","difficulty":"very-hard"},
  {"id":"eng-grammar-13","question":"Fill in the blank: She has been working here ____ 2015.","options":["for","since","from","until"],"answer":1,"explanation":"'Since' marks a point of time from which the action continues to now; 'for' marks a duration ('for six years'). 'From' needs a matching end point, and 'until' would end the action, which clashes with 'has been working'.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"eng-grammar-14","question":"Spot the error: One of my friends (a) / are going (b) / to Delhi tomorrow. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"'One of my friends' has the singular subject 'one', so part (b) should read 'is going'. 'Friends' is only the object of 'of' and does not control the verb.","difficulty":"easy","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-15","question":"Choose the correct passive form: “They are building a new bridge.”","options":["A new bridge is built by them.","A new bridge is being built by them.","A new bridge was built by them.","A new bridge has been built by them."],"answer":1,"explanation":"Present continuous active → “is/are being + past participle” in the passive.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-16","question":"Spot the error: Neither of the two boys (a) / have submitted (b) / their homework. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"“Neither of” takes a singular verb: “has submitted his homework”.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-17","question":"Choose the correct indirect speech: He said, “I am going to the market now.”","options":["He said that he is going to the market just now.","He said that he was going to the market then.","He said that he was going to the market now.","He told that he is going to the market then."],"answer":1,"explanation":"In reported speech after a past reporting verb, 'am' shifts back to 'was' and 'now' becomes 'then'. 'Told' needs an object ('told me'), and keeping 'is' or 'now' fails the backshift.","difficulty":"hard","source":"SSC CGL · SBI PO"},
  {"id":"eng-grammar-18","question":"Spot the error: The number of accidents (a) / on this road (b) / have increased sharply. (c) / No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"“The number of” is singular: “has increased”. (“A number of” would take a plural verb.)","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-grammar-19","question":"Spot the error: Scarcely had he reached the station (a) / than the train (b) / started moving. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"'Scarcely' and 'hardly' pair with 'when' (or 'before'), so part (b) should read 'when the train'. 'Than' belongs only with 'no sooner', the usual mix-up.","difficulty":"hard"},
  {"id":"eng-grammar-20","question":"Choose the correct option: “If I ___ a bird, I would fly to you.”","options":["was","were","am","had been"],"answer":1,"explanation":"An imaginary present condition takes the subjunctive “were” for all subjects.","difficulty":"hard"},
  {"id":"eng-grammar-21","question":"Spot the error: He is one of those writers (a) / who has won (b) / several awards this year. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"“Who” refers to “writers” (plural), so it should be “who have won”.","difficulty":"very-hard"},
  {"id":"eng-grammar-22","question":"Choose the correct passive form of: “Who taught you this trick?”","options":["By whom were you taught this trick?","By whom you were taught this trick?","Who was taught this trick by you?","This trick was taught by whom to you?"],"answer":0,"explanation":"Questions keep the question order in the passive: By whom + auxiliary + subject + past participle.","difficulty":"very-hard"},
  {"id":"eng-grammar-23","question":"Spot the error: No sooner did the bell ring (a) / when the students (b) / rushed out of the class. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"'No sooner' is a comparative and pairs with 'than', so part (b) should read 'than the students'. 'When' goes with 'scarcely' and 'hardly', not with 'no sooner'.","difficulty":"very-hard"},
  {"id":"eng-grammar-24","question":"Choose the correct option: “The committee ___ divided in their opinions.”","options":["was","were","has been","is being"],"answer":1,"explanation":"When members act as individuals (“their opinions”), a collective noun takes a plural verb.","difficulty":"very-hard"},
  {"id":"eng-grammar-25","question":"Spot the part with the error: “Neither the manager nor the employees / was aware / of the new policy.”","options":["Neither the manager nor the employees","was aware","of the new policy","No error"],"answer":1,"explanation":"With neither … nor, the verb agrees with the nearer subject, “employees”, so it should be “were aware”.","difficulty":"very-hard"},
  {"id":"eng-grammar-26","question":"Which sentence is correct?","options":["Scarcely had he left when it started raining.","Scarcely had he left than it started raining.","Scarcely he had left when it started raining.","Scarcely did he left when it started raining."],"answer":0,"explanation":"“Scarcely” and “hardly” take “when”, not “than”, and put the auxiliary before the subject.","difficulty":"very-hard"},
  {"id":"eng-grammar-27","question":"Fill in the blank: “The committee ___ divided in their opinions.”","options":["is","are","was being","has"],"answer":1,"explanation":"When a collective noun’s members act separately (“their opinions”), it takes a plural verb.","difficulty":"very-hard"},
  {"id":"eng-grammar-28","question":"Which sentence has NO error?","options":["Each of the players have given their best.","One of my friend is a doctor.","Neither of the answers is correct.","The sceneries of Kashmir is beautiful."],"answer":2,"explanation":"“Neither of” takes a singular verb. The others need “has given his best”, “one of my friends” and “the scenery … is” (scenery is uncountable).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-29","question":"Spot the part with the error: “The principal, along with the teachers, / were present / at the function.”","options":["The principal, along with the teachers,","were present","at the function","No error"],"answer":1,"explanation":"Words joined by “along with”, “as well as” or “together with” do not change the number of the subject: “the principal … was present”.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-30","question":"Fill in the blank: She ___ her homework before dinner yesterday.","options":["finishes","finished","finish","finishing"],"answer":1,"explanation":"'Yesterday' fixes the time in the past, so the simple past 'finished' is needed.","difficulty":"easy","source":"SSC GD · RRB Group D"},
  {"id":"eng-grammar-31","question":"Fill in the blank: ___ apple a day keeps the doctor away.","options":["A","The","An","No article"],"answer":2,"explanation":"'Apple' begins with a vowel sound, so the indefinite article is 'an'.","difficulty":"easy","source":"SSC GD · SSC CHSL"},
  {"id":"eng-grammar-32","question":"Fill in the blank: The children ___ playing in the park.","options":["is","am","was","are"],"answer":3,"explanation":"'Children' is plural, so the plural present verb 'are' is required.","difficulty":"easy","source":"SSC GD · RRB NTPC"},
  {"id":"eng-grammar-33","question":"Spot the error: Mathematics (a) / are (b) / my favourite subject. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"Names of subjects ending in -s (mathematics, physics, economics) are singular: 'Mathematics is my favourite subject'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-34","question":"Fill in the blank: He is good ___ mathematics.","options":["in","at","with","on"],"answer":1,"explanation":"The fixed preposition after 'good' for a skill or subject is 'at': good at mathematics. 'Good in' is a common Indian-English error.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"eng-grammar-35","question":"Spot the error: The furnitures (a) / in this room (b) / are very old. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"'Furniture' is an uncountable noun and has no plural: 'The furniture in this room is very old' (so the verb changes to 'is' as well, but the error lies in part (a)).","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-36","question":"Fill in the blank: I have known him ___ ten years.","options":["since","from","during","for"],"answer":3,"explanation":"'For' goes with a length of time (ten years); 'since' needs a point of time (since 2015).","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk"},
  {"id":"eng-grammar-37","question":"Improve the underlined part: He has returned back from Delhi.","options":["has returned","had returned back","returned back","No improvement"],"answer":0,"explanation":"'Return' already means 'come back', so 'returned back' is a redundancy. 'He has returned from Delhi' is correct.","difficulty":"moderate","source":"SSC CGL · SSC CPO"},
  {"id":"eng-grammar-38","question":"Spot the error: She is (a) / more smarter (b) / than her sister. (c) / No error (d)","options":["(c)","(b)","(a)","(d)"],"answer":1,"explanation":"'Smarter' is already comparative; adding 'more' makes a double comparative. Use 'smarter than'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-39","question":"Spot the error: The police (a) / has arrested (b) / the thief. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'Police' is a plural noun (like 'people' and 'cattle') and takes a plural verb: 'The police have arrested the thief'.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-40","question":"Fill in the blank: Unless you ___ hard, you will not pass.","options":["work","will work","worked","do not work"],"answer":0,"explanation":"'Unless' means 'if … not' and takes the simple present, not 'will'. 'Unless you do not work' doubles the negative.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-41","question":"Improve the underlined part: No sooner did he see the police when he ran away.","options":["then he ran away","as he ran away","than he ran away","No improvement"],"answer":2,"explanation":"'No sooner' is a comparative and must be followed by 'than', not 'when' or 'then'.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-42","question":"Spot the error: Many a student (a) / have failed (b) / in the examination. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'Many a' is followed by a singular noun and a singular verb, even though the meaning is plural: 'Many a student has failed'.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-grammar-43","question":"Fill in the blank: I would rather die ___ beg.","options":["then","to","than","but"],"answer":2,"explanation":"'Would rather' expresses preference and is followed by 'than' (not 'then' or 'to'): rather die than beg.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-44","question":"Spot the error: He insisted (a) / to go (b) / to the party. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'Insist' takes 'on' + gerund, not an infinitive: 'He insisted on going to the party'.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-45","question":"Change into the active voice: Let the door be closed.","options":["Let the door close.","Close the door.","Someone closes the door.","The door closes."],"answer":1,"explanation":"'Let + object + be + past participle' is the passive of an imperative. Its active form is the plain imperative: 'Close the door.'","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-46","question":"Spot the error: She likes (a) / singing, dancing (b) / and to paint. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"Items in a list must be parallel. 'Singing, dancing' are gerunds, so the third must be 'painting', not the infinitive 'to paint'.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"eng-grammar-47","question":"Change into indirect speech: She said to me, “Do you like tea?”","options":["She asked me that I liked tea.","She asked me do I like tea.","She asked me if I like tea.","She asked me if I liked tea."],"answer":3,"explanation":"A yes/no question becomes 'asked … if/whether', the question order becomes statement order, and the present 'like' shifts to the past 'liked' after the past reporting verb.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-48","question":"Spot the error: Either the students (a) / or the teacher (b) / are responsible for the mess. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"With 'either … or' the verb agrees with the nearer subject. 'The teacher' is nearer and singular, so it should be 'is responsible'. The plural 'students' earlier in the sentence is the trap.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-49","question":"Spot the error: The sceneries (a) / of Kashmir (b) / are breathtaking. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"'Scenery' is uncountable and has no plural form: 'The scenery of Kashmir is breathtaking'. The error is the noun in part (a).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-50","question":"Spot the error: One of the most (a) / important question (b) / was left unanswered. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'One of the' is followed by a plural noun: 'one of the most important questions'. The singular verb 'was' is correct because the subject is 'one'.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-grammar-51","question":"Improve the underlined part: If I would have known, I would have helped you.","options":["If I knew","Had I have known","If I had known","No improvement"],"answer":2,"explanation":"A third conditional uses the past perfect in the if-clause: 'If I had known, I would have helped'. 'Would have' belongs only in the main clause.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-52","question":"Spot the error: He is (a) / the most unique (b) / artist of his time. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'Unique' is an absolute adjective meaning 'one of a kind' and cannot be graded: 'the most unique' should be 'a unique' or 'the most unusual'.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"eng-grammar-53","question":"Fill in the blank: The teacher, as well as the students, ___ invited.","options":["were","was","are","have been"],"answer":1,"explanation":"With 'as well as', 'along with' or 'together with', the verb agrees with the first subject only. 'The teacher' is singular, so 'was invited'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-54","question":"Spot the error: The two brothers (a) / do not talk (b) / to one another. (c) / No error (d)","options":["(d)","(a)","(c)","(b)"],"answer":2,"explanation":"'Each other' is used for two persons and 'one another' for more than two. With 'the two brothers' it should be 'to each other'.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-grammar-55","question":"Spot the error: She prefers (a) / coffee more than (b) / tea. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'Prefer' is followed by 'to', never by 'more than': 'She prefers coffee to tea'.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-56","question":"Improve the underlined part: He ordered for a cup of coffee.","options":["ordered to a cup of coffee","No improvement","ordered a cup of coffee","ordered about a cup of coffee"],"answer":2,"explanation":"'Order' takes a direct object without a preposition: 'He ordered a cup of coffee'. 'Order for' is a common Indian-English error.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-57","question":"Spot the error: Being a rainy day, (a) / we decided (b) / to stay at home. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"The participle 'being' has no subject and wrongly attaches to 'we' (a dangling modifier). Correct: 'It being a rainy day, we decided to stay at home'.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"eng-grammar-58","question":"Change into the passive voice: The teacher will have finished the lesson by noon.","options":["The lesson will be finished by the teacher by noon.","The lesson will have finished by noon.","The lesson will have been finished by the teacher by noon.","The lesson would have been finished by the teacher by noon."],"answer":2,"explanation":"Future perfect active 'will have finished' becomes 'will have been finished' in the passive. Dropping 'been' or changing to 'will be' alters the tense.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-59","question":"Spot the error: I have seen him (a) / yesterday (b) / at the station. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"The present perfect cannot be used with a definite past time like 'yesterday'. The verb in part (a) should be the simple past: 'I saw him yesterday'.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id": "eng-grammar-60", "question": "Fill in the blank: The sun ___ in the east.", "options": ["rose", "rises", "is rising", "rise"], "answer": 1, "explanation": "Universal truths take the simple present: 'The sun rises in the east.' A singular subject takes 'rises', not 'rise'.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id":"eng-grammar-61","question":"Fill in the blank: She is fond ___ music.","options":["of","with","for","in"],"answer":0,"explanation":"'Fond' always takes 'of': fond of music. 'Fond for' and 'fond with' are common errors, carried over from phrases like 'love for' and 'pleased with'.","difficulty":"easy","source":"RRB NTPC · SSC CHSL"},
  {"id": "eng-grammar-62", "question": "Spot the error: He did not knew (a) / the answer (b) / to the question. (c) / No error (d)", "options": ["(b)", "(c)", "(d)", "(a)"], "answer": 3, "explanation": "After the auxiliary 'did', the main verb takes its base form: 'He did not know'. 'Did not knew' marks the past twice.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-63", "question": "Fill in the blank: Each boy and each girl ___ given a book.", "options": ["were", "are", "was", "have been"], "answer": 2, "explanation": "When two singular subjects joined by 'and' are each preceded by 'each' or 'every', the verb is singular: 'was given'.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-64","question":"Fill in the blank: Neither Ram nor his friends ___ come yet.","options":["has","have","does","was"],"answer":1,"explanation":"With 'neither … nor' the verb agrees with the nearer subject. 'Friends' is plural, so 'have come'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-65","question":"Change into the passive voice: Open the window.","options":["Let the window be opened.","The window is being opened.","The window should open.","Let the window open."],"answer":0,"explanation":"An imperative becomes passive with 'Let + object + be + past participle': 'Let the window be opened.'","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-66", "question": "Spot the error: I am looking forward (a) / to meet you (b) / next week. (c) / No error (d)", "options": ["(a)", "(c)", "(d)", "(b)"], "answer": 3, "explanation": "In 'look forward to', 'to' is a preposition, so it takes a gerund: 'to meeting you'.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-67", "question": "Spot the error: The quality of the mangoes (a) / were not (b) / up to the mark. (c) / No error (d)", "options": ["(a)", "(c)", "(b)", "(d)"], "answer": 2, "explanation": "The subject is 'quality' (singular); 'of the mangoes' only describes it. So 'was not', not 'were not'.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-68", "question": "Change into indirect speech: He said, “I have finished my work.”", "options": ["He said that he has finished his work.", "He said that he had finished his work.", "He said that I had finished my work.", "He said that he finished his work."], "answer": 1, "explanation": "With a past reporting verb, the present perfect 'have finished' moves back to past perfect 'had finished', and 'I/my' become 'he/his'.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-69", "question": "Spot the error: Unless you do not work hard (a) / you will not (b) / pass. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 0, "explanation": "'Unless' already means 'if not', so 'unless you do not' is a double negative. Correct: 'Unless you work hard, you will not pass.'", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-70", "question": "Fill in the blank: Ten kilometres ___ a long distance to walk.", "options": ["are", "were", "have been", "is"], "answer": 3, "explanation": "A plural amount of distance, money or time treated as one whole takes a singular verb: 'Ten kilometres is a long distance.'", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-71", "question": "Spot the error: He is taller (a) / than any boy (b) / in the class. (c) / No error (d)", "options": ["(a)", "(c)", "(b)", "(d)"], "answer": 2, "explanation": "He is himself a boy in the class, so he must be compared with the others: 'than any other boy'. Otherwise he is compared with himself.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-72","question":"Fill in the blank: Had she studied harder, she ___ the examination.","options":["would pass","would have passed","would have been passed","had passed"],"answer":1,"explanation":"'Had she studied' is the inverted past-perfect condition (third conditional), so the result clause takes active 'would have + past participle'. 'Would have been passed' is passive, which makes no sense with 'she' as the one taking the exam.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-73","question":"Spot the error: The cattle (a) / is grazing (b) / in the field. (c) / No error (d)","options":["(b)","(a)","(c)","(d)"],"answer":0,"explanation":"'Cattle' is a plural noun with no singular form, so it takes a plural verb: 'are grazing'. The error is in part (b); 'The cattle' in part (a) is itself correct.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-74", "question": "Spot the error: Not only the students (a) / but also the teacher (b) / were punished. (c) / No error (d)", "options": ["(a)", "(b)", "(d)", "(c)"], "answer": 3, "explanation": "With 'not only … but also' the verb agrees with the nearer subject, 'the teacher' (singular): 'was punished'.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-75", "question": "Change into the passive voice: People believe that he is honest.", "options": ["He was believed to be honest.", "It is believed by people he is honest.", "He is believed to be honest.", "He is believed being honest."], "answer": 2, "explanation": "'People believe that X is …' becomes 'X is believed to be …', keeping the present tense. 'Was believed' changes the tense.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-76", "question": "Change into indirect speech: She said to him, “Please wait here till I return.”", "options": ["She told him to please wait here till she returns.", "She requested him to wait there till she returned.", "She requested him that he waits there till she returned.", "She ordered him to wait here till she returned."], "answer": 1, "explanation": "'Please' becomes the reporting verb 'requested' + infinitive. 'Here' becomes 'there' and 'return' moves back to 'returned'.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-77", "question": "Spot the error: Despite of (a) / his illness, (b) / he attended the meeting. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 0, "explanation": "'Despite' never takes 'of'. Say 'despite his illness' or 'in spite of his illness'.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-78", "question": "Spot the error: It is high time (a) / we leave (b) / for the station. (c) / No error (d)", "options": ["(a)", "(c)", "(d)", "(b)"], "answer": 3, "explanation": "'It is high time' is followed by the past subjunctive: 'It is high time we left.' The present form is the usual slip.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id":"eng-grammar-79","question":"Which sentence is grammatically correct?","options":["Bread and butter are my staple breakfast every morning.","Physics are my favourite subject at school this year.","The Prime Minister, along with his ministers, has arrived.","Every man and woman in the village were present at the meeting."],"answer":2,"explanation":"A subject joined by 'along with' keeps its own number, so 'The Prime Minister … has arrived' is right. 'Bread and butter' is one dish (is), 'Physics' is singular (is), and 'every … and …' takes 'was'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-80", "question": "Fill in the blank: He talks as if he ___ the owner of the house.", "options": ["is", "were", "was being", "has been"], "answer": 1, "explanation": "'As if' for something untrue takes the past subjunctive 'were' for all persons: 'as if he were the owner'.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-81", "question": "Spot the error: The reason why he failed (a) / is because (b) / he did not study. (c) / No error (d)", "options": ["(b)", "(a)", "(c)", "(d)"], "answer": 0, "explanation": "'The reason … is because' repeats the idea of cause. Correct: 'The reason why he failed is that he did not study.'", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-82", "question": "Spot the error: My brother-in-laws (a) / are coming (b) / to stay with us. (c) / No error (d)", "options": ["(b)", "(c)", "(d)", "(a)"], "answer": 3, "explanation": "In compound nouns the main word takes the plural: 'brothers-in-law', not 'brother-in-laws'.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-83", "question": "Change into the passive voice: Did they complete the project on time?", "options": ["Was the project being completed by them on time?", "Has the project been completed by them on time?", "Was the project completed by them on time?", "Did the project complete by them on time?"], "answer": 2, "explanation": "A simple-past question with 'did' becomes 'Was/Were + subject + past participle': 'Was the project completed by them on time?'", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-84","question":"Change into indirect speech: He said, “Let us go for a walk.”","options":["He said that let us go for a walk.","He suggested that they should go for a walk.","He ordered them that they should go for a walk.","He suggested that we should go for a walk."],"answer":1,"explanation":"'Let us' expressing a proposal becomes 'suggested/proposed that they should …'. 'Us' changes to 'they'; 'ordered' changes the meaning.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-85", "question": "Fill in the blank: She is ___ European.", "options": ["an", "the", "no article", "a"], "answer": 3, "explanation": "Use 'a' because European begins with a 'yoo' (consonant) sound, even though it starts with a vowel letter.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "eng-grammar-86", "question": "Fill in the blank: Would you mind ___ the door?", "options": ["closed", "close", "to close", "closing"], "answer": 3, "explanation": "'Mind' is followed by the -ing form: 'Would you mind closing the door?'", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "eng-grammar-87", "question": "Fill in the blank: The scissors ___ on the table.", "options": ["was", "has been", "is", "are"], "answer": 3, "explanation": "'Scissors' is a plural-only noun (like trousers, spectacles), so it takes a plural verb: are.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "eng-grammar-88", "question": "Spot the error: This plan will fail, (a) / and it is a secret (b) / between you and I. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 2, "explanation": "A preposition takes the object form of a pronoun: 'between you and me'. 'I' is the subject form.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-89", "question": "Fill in the blank: I am used to ___ up early.", "options": ["got", "have got", "get", "getting"], "answer": 3, "explanation": "In 'be used to', 'to' is a preposition, so the -ing form follows: 'I am used to getting up early'. Compare 'I used to get up early' (past habit).", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-90", "question": "Spot the error: My cousin is (a) / married with (b) / a doctor from Pune. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 1, "explanation": "One is married to a person, not 'with': 'married to a doctor'.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-91", "question": "Fill in the blank: He was accused ___ theft.", "options": ["of", "about", "for", "with"], "answer": 0, "explanation": "The fixed preposition is 'accused of'. Compare 'charged with theft'.", "difficulty": "moderate", "source": "RRB NTPC · SSC CHSL"},
  {"id": "eng-grammar-92", "question": "Spot the error: All the new (a) / equipments in the lab (b) / are kept locked. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 1, "explanation": "'Equipment' is uncountable and has no plural: 'All the new equipment in the lab is kept locked'.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-93", "question": "Choose the correct question tag: Nobody called while I was out, ___?", "options": ["didn't he", "did he", "didn't they", "did they"], "answer": 3, "explanation": "'Nobody' makes the sentence negative, so the tag is positive; indefinite pronouns like nobody take 'they' in tags: 'did they?'", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-94", "question": "Spot the error: The members of the committee (a) / discussed about (b) / the problem at length. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 1, "explanation": "'Discuss' takes a direct object; 'about' is redundant: 'discussed the problem'. (The noun form does take it: 'a discussion about'.)", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-95", "question": "Fill in the blank: Walk carefully lest you ___.", "options": ["should fall", "will fall", "would fall", "may not fall"], "answer": 0, "explanation": "'Lest' is followed by 'should' + base verb (or the bare subjunctive), never by 'will' and never by 'not', since lest already means 'in case … not'.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-96", "question": "Spot the error: In every society, (a) / the poor is (b) / often neglected. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 1, "explanation": "'The + adjective' (the poor, the rich) refers to a group of people and is plural: 'the poor are often neglected'.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-97", "question": "Spot the error: He enjoyed (a) / at the party (b) / last night. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 0, "explanation": "'Enjoy' needs an object; with no other object it takes a reflexive pronoun: 'He enjoyed himself at the party'.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-98", "question": "Spot the error: The harder you practise (a) / for the match, (b) / more confident you will become. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 2, "explanation": "The double comparative needs 'the' in both halves: 'The harder you practise …, the more confident you will become'.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-99", "question": "Spot the error: When the chance came, (a) / he availed of (b) / the opportunity to meet the minister. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 1, "explanation": "'Avail' in this sense needs a reflexive pronoun: 'he availed himself of the opportunity'.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-100", "question": "Fill in the blank: You had better ___ a doctor.", "options": ["consulted", "to consult", "consulting", "consult"], "answer": 3, "explanation": "'Had better' is followed by the bare infinitive: 'You had better consult a doctor'.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "eng-grammar-101", "question": "Spot the error: I am sure that hardly anyone (a) / in this village (b) / has never seen a tiger. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 2, "explanation": "'Hardly' is already negative, so 'never' makes a double negative. Use 'has ever seen a tiger'.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-102", "question": "Spot the error: The new house has a garden (a) / and it (b) / comprises of four bedrooms. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 2, "explanation": "'Comprise' means 'consist of' and takes no 'of': 'it comprises four bedrooms' (or 'consists of four bedrooms').", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-103", "question": "Spot the error: Whom do you think (a) / is the best candidate (b) / for the post? (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 0, "explanation": "'Do you think' is a parenthetical insert; the pronoun is the subject of 'is', so it must be 'Who': 'Who do you think is the best candidate?'", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-104", "question": "Spot the error: What will you do (a) / supposing if (b) / it rains tomorrow? (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 1, "explanation": "'Supposing' already means 'if', so 'supposing if' is redundant. Use 'supposing it rains' or 'if it rains'.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-105", "question": "Spot the error: One should always (a) / try to do (b) / his duty honestly. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 2, "explanation": "When the subject is 'one', the possessive that follows should be 'one's': 'One should always try to do one's duty honestly'.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-106", "question": "Spot the error: The murderer was hung (a) / at dawn (b) / after the trial. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 0, "explanation": "For execution by hanging, the past participle is 'hanged': 'The murderer was hanged'. 'Hung' is used for objects (the picture was hung).", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-107", "question": "Choose the correct question tag: Let's go for a walk, ___?", "options": ["shall we", "don't we", "won't we", "will you"], "answer": 0, "explanation": "A suggestion with 'Let's' (let us) takes the tag 'shall we?'. 'Will you?' is the tag for a request or order beginning with 'Let' (Let me go, will you?).", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-108", "question": "Spot the error: Scarcely had the guests arrived (a) / when the lights (b) / went out. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 3, "explanation": "The sentence is correct: 'scarcely' (like 'hardly') pairs with 'when', with the inverted 'had the guests arrived'. 'Than' is used only with 'no sooner'.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-109", "question": "Improve the sentence: He is too weak that he cannot walk.", "options": ["too weak that he could not walk", "so weak that he cannot walk", "very weak that he cannot walk", "No improvement"], "answer": 1, "explanation": "'Too' pairs with 'to' (too weak to walk) and 'so' pairs with 'that' (so weak that he cannot walk). 'Too … that' mixes the two patterns.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-110", "question": "Spot the error: Feeling unwell, (a) / he has laid in bed (b) / all morning. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 1, "explanation": "The intransitive verb 'lie' (lie, lay, lain) is needed: 'he has lain in bed'. 'Laid' belongs to the transitive 'lay' (to put something down).", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-111", "question": "Fill in the blank: It is I who ___ to blame.", "options": ["was", "is", "am", "are"], "answer": 2, "explanation": "In a relative clause the verb agrees with the antecedent of 'who', which here is 'I': 'It is I who am to blame'.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-112", "question": "How many of these sentences are grammatically correct? 1. The jury has given its verdict. 2. The cattle are grazing in the field. 3. Mathematics is my favourite subject. 4. The news are good.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "1 is correct (the jury acting as one body), 2 is correct (cattle is always plural) and 3 is correct (mathematics is singular). 4 is wrong: 'news' is uncountable, so 'The news is good'. Only three.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-113", "question": "Spot the error: Not only he sang (a) / but also danced (b) / at the function. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 0, "explanation": "'Not only … but also' must join parallel parts. With 'danced' after 'but also', 'not only' must come before 'sang': 'He not only sang but also danced'.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id":"eng-grammar-114","question":"Choose the correct indirect speech: He said, “What a beautiful day it is!”","options":["He exclaimed that it was a very beautiful day.","He exclaimed with joy that what a beautiful day it was.","He exclaimed what a beautiful day it is.","He asked what a beautiful day it was."],"answer":0,"explanation":"An exclamation is reported with a verb like 'exclaimed', 'what a' becomes 'very', and the tense shifts back (is → was). 'Asked' is for questions.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"eng-grammar-115","question":"Spot the error: He did not attend the meeting (a) / because of he was (b) / unwell. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'Because of' is a preposition and must be followed by a noun ('because of his illness'). Before a clause ('he was unwell') the conjunction 'because' is needed.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-116","question":"Fill in the blank: If it ___ tomorrow, the match will be postponed.","options":["would rain","will rain","rains","rained"],"answer":2,"explanation":"In a first conditional, the if-clause takes the simple present and the main clause takes 'will': 'If it rains, the match will be postponed'. 'Will rain' in the if-clause is the common error.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-117","question":"Choose the correct question tag: He has gone to Delhi, ___?","options":["doesn't he","didn't he","isn't he","hasn't he"],"answer":3,"explanation":"A positive statement takes a negative tag with the same auxiliary: 'has' → 'hasn't he'.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-118","question":"Fill in the blank: She plays ___ violin beautifully.","options":["a","the","an","no article"],"answer":1,"explanation":"The definite article is used before musical instruments when we speak of playing them: 'plays the violin'. (Games, by contrast, take no article: 'plays cricket'.)","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-119","question":"Spot the error: She has been suffering (a) / from fever (b) / for the last Monday. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"A point of time takes 'since': 'since last Monday'. 'For' is used with a period of time ('for three days').","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-120","question":"Change into indirect speech: He said to me, “Don't make a noise.”","options":["He told me not to make a noise.","He told me that don't make a noise.","He said to me that I did not make a noise.","He asked me that I should not made a noise."],"answer":0,"explanation":"A negative imperative is reported with 'told/ordered + object + not to + verb': 'He told me not to make a noise'.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-121","question":"Spot the error: By the time the fire brigade arrived, (a) / the whole building (b) / has been gutted. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"The earlier of two past actions takes the past perfect: 'had been gutted'. The present perfect cannot follow a past-time clause like 'by the time ... arrived'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-122","question":"Spot the error: He told me that (a) / he will meet me (b) / at the station the next day. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"After a past reporting verb ('told'), 'will' changes to 'would': 'he would meet me'. 'The next day' already shows the shift into reported speech.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-123","question":"Spot the error: The teacher said that (a) / the earth moved (b) / round the sun. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"A universal truth keeps the present tense even after a past reporting verb: 'the earth moves round the sun'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-124","question":"Spot the error: He is (a) / an university professor (b) / of great repute. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'University' begins with a 'yoo' (consonant) sound, so it takes 'a': 'a university professor'. The article depends on sound, not spelling.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-125","question":"Spot the error: Though he is rich, (a) / but he is not happy (b) / at all. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'Though' is not paired with 'but'. Either drop 'but' or use 'yet': 'Though he is rich, he is not happy' / 'Though he is rich, yet he is not happy'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-126","question":"Spot the error: He made me (a) / to understand (b) / the problem clearly. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"In the active voice 'make' takes the bare infinitive: 'made me understand'. 'To' appears only in the passive ('I was made to understand').","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-127","question":"Fill in the blank: Neither he nor I ___ going to the wedding.","options":["are","am","is","were"],"answer":1,"explanation":"With 'neither ... nor', the verb agrees with the nearer subject, here 'I': 'Neither he nor I am going'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-128","question":"Fill in the blank: I agree ___ your proposal, but I do not agree ___ you on every point.","options":["to, with","with, to","with, with","on, to"],"answer":0,"explanation":"We agree TO a proposal, plan or suggestion, but agree WITH a person (or an opinion).","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-129","question":"Fill in the blank: Many people in the village died ___ cholera that year.","options":["by","from","of","with"],"answer":2,"explanation":"'Die of' is used with a disease ('died of cholera'); 'die from' is used with an external cause such as a wound or overwork.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-130","question":"Change into the passive voice: Everyone knows him.","options":["He has been known by everyone.","He is known by everyone.","He was known to everyone.","He is known to everyone."],"answer":3,"explanation":"The tense stays simple present ('is known'), and the verb 'know' takes 'to' rather than 'by' in the passive: 'He is known to everyone'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-131","question":"Change into indirect speech: She said, “Will you help me, Mohan?”","options":["She asked Mohan will he help her.","She asked Mohan if he would help her.","She told Mohan that he will help her.","She asked Mohan if he will help me."],"answer":1,"explanation":"A yes/no question is reported with 'asked + if/whether', statement word order, 'will' → 'would' and pronouns adjusted: 'She asked Mohan if he would help her'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-132","question":"Choose the correct question tag: Everybody enjoyed the show, ___?","options":["didn't they","didn't he","did they","didn't everybody"],"answer":0,"explanation":"Indefinite pronouns like everybody/everyone take 'they' in the tag, never the pronoun itself; a positive statement in the simple past takes 'didn't': 'didn't they?'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-133","question":"Spot the error: Not until the results were declared (a) / he realised (b) / how badly he had done. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"When a sentence begins with 'Not until ...', the main clause is inverted: 'did he realise'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-134","question":"Spot the error: Seldom we come across (a) / such a dedicated (b) / social worker. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"A negative adverb like 'seldom' at the start of a sentence requires inversion: 'Seldom do we come across ...'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-135","question":"Spot the error: Bread and butter (a) / are (b) / his usual breakfast. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'Bread and butter' names a single dish, so it takes a singular verb: 'Bread and butter is his usual breakfast'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-136","question":"Spot the error: A large number of students (a) / has registered (b) / for the new course. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'A number of' means 'many' and takes a plural verb: 'have registered'. It is 'THE number of' that takes a singular verb.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-137","question":"Spot the error: She is the most intelligent (a) / of all the other (b) / girls in the class. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"With a superlative, 'other' is wrong because she is included in the group: 'the most intelligent of all the girls'. 'Other' belongs with a comparative ('more intelligent than any other girl').","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-138","question":"Spot the error: No sooner had I opened the door (a) / than the dog (b) / ran out into the street. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":3,"explanation":"The sentence is correct: 'No sooner' is followed by inversion ('had I opened') and correctly paired with 'than'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-139","question":"Spot the error: Neither of the two candidates (a) / is suitable (b) / for the post. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":3,"explanation":"The sentence is correct. 'Neither' (of two) is singular and takes 'is'. Changing it to 'are' would be the error.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-140","question":"Spot the error: The boy was so tired (a) / that he could not (b) / hardly walk. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"'Hardly' is already negative, so 'could not hardly' is a double negative. It should be 'he could hardly walk'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-141","question":"Spot the error: Ten years have passed (a) / since he has left (b) / his native village. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"A 'since' clause that marks a point in the past takes the simple past: 'since he left'. The present perfect belongs to the main clause.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-142","question":"Spot the error: The officer asked me (a) / where was I going (b) / so late at night. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"In an indirect question the word order is that of a statement: 'where I was going'. Question order ('was I') is used only in direct speech.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-143","question":"Fill in the blank: Were he to apologise sincerely, I ___ him.","options":["forgive","will forgive","would have forgiven","would forgive"],"answer":3,"explanation":"'Were he to ...' is an inverted second conditional ('If he were to apologise'), so the main clause takes 'would + base verb'. 'Would have forgiven' belongs to the third conditional.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-144","question":"Choose the correct question tag: I am right, ___?","options":["am not I","amn't I","aren't I","isn't it"],"answer":2,"explanation":"The standard negative tag for 'I am' is the irregular 'aren't I?'. 'Amn't I' is not accepted in standard English.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-145","question":"Spot the error: Let you and I (a) / go together (b) / to the village fair. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"'Let' is followed by the object form of the pronoun: 'Let you and me go'. 'I' is a subject pronoun and cannot be the object of 'let'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-146","question":"Spot the error: Hardly I had reached (a) / the office (b) / when the meeting began. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"A sentence opening with 'Hardly' needs inversion: 'Hardly had I reached the office when ...'. 'When' is the correct partner of 'hardly'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-147","question":"Spot the error: Myself and my sister (a) / will attend (b) / the function tomorrow. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"A reflexive pronoun cannot be used as a subject. The correct form is 'My sister and I will attend', with the first person placed last out of courtesy.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-148","question":"Spot the error: Since the exam has been postponed, (a) / you need not (b) / to worry about it now. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"'Need' used as a modal (in 'need not') takes the bare infinitive: 'you need not worry'. 'To' is used only with the ordinary verb: 'you do not need to worry'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-149","question":"Fill in the blank: Two-thirds of the students ___ absent on the day of the strike.","options":["was","has been","is","were"],"answer":3,"explanation":"With fractions, the verb agrees with the noun after 'of'. 'Students' is plural, so 'were'. (Compare: 'Two-thirds of the cake was eaten'.)","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-150","question":"Fill in the blank: A pair of new shoes ___ lying under the bed.","options":["were","are","was","have been"],"answer":2,"explanation":"The subject is 'a pair', which is singular, so the verb is 'was'. 'Shoes' is only the object of the preposition 'of'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-151","question":"Fill in the blank: 'Gulliver's Travels' ___ written by Jonathan Swift.","options":["have been","were","was","are"],"answer":2,"explanation":"The title of a book is treated as singular, even when it looks plural: 'Gulliver's Travels was written by Swift'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-152","question":"Fill in the blank: He is ___ one-eyed man who sells toys near the temple.","options":["the","an","a","no article"],"answer":2,"explanation":"'One' begins with a 'w' (consonant) sound, so it takes 'a': 'a one-eyed man'. 'An' is the trap, since the word begins with a vowel letter.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-153","question":"Change into the passive voice: Somebody must have stolen my bag.","options":["My bag must be stolen by somebody.","My bag must have been stolen.","My bag must have stolen.","My bag must had been stolen by somebody."],"answer":1,"explanation":"A perfect modal 'must have + V3' becomes 'must have been + V3' in the passive. The agent 'somebody' is usually dropped.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-154","question":"Spot the error: During the holidays (a) / she did nothing (b) / but to complain about the heat. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"After 'do nothing but', the bare infinitive is used: 'did nothing but complain'. 'To' is wrong here.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-155","question":"Spot the error: The secretary and treasurer of the club (a) / has been arrested (b) / for misusing funds. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":3,"explanation":"There is no error. The article 'the' appears only once, so 'secretary and treasurer' is one person holding two posts, and the singular 'has' is correct. 'The secretary and the treasurer' would mean two people and need 'have'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-156","question":"Spot the error: Of all the boys in the class, (a) / he is the only one (b) / who have passed in every subject. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"After 'the only one', the relative pronoun refers to 'one' (singular), so the verb is 'has passed'. In 'one of the boys who have passed' the plural would be correct — but 'the only one' singles him out.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-157","question":"Spot the error: I have been knowing him (a) / since my school days (b) / and trust him completely. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"'Know' is a stative verb and is not used in continuous tenses: 'I have known him since my school days'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-158","question":"Spot the error: Please explain me (a) / how this machine (b) / works. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"'Explain' does not take a person as a direct object; it needs 'to': 'Please explain to me how this machine works'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-159","question":"Spot the error: Ram is elder (a) / than his cousin (b) / by two years. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"'Elder' is not followed by 'than'; with 'than' we use 'older': 'Ram is older than his cousin'. 'Elder' is used attributively ('my elder brother').","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-160","question":"Spot the error: Each one of the members (a) / was given (b) / a copy of the report. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":3,"explanation":"The sentence is correct: the subject is 'each one', which is singular, so 'was given' is right. Changing it to 'were' because of 'members' would be the error.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-161","question":"Fill in the blank: More than one student ___ absent from the class today.","options":["have been","were","are","was"],"answer":3,"explanation":"Although its meaning is plural, 'more than one' + singular noun takes a singular verb: 'More than one student was absent'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-162","question":"Fill in the blank: None of the milk ___ spilt when the jug fell.","options":["were","have been","was","are"],"answer":2,"explanation":"'None' takes the number of the noun it refers to. 'Milk' is uncountable, so the verb is singular: 'None of the milk was spilt'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-163","question":"Fill in the blank: The United States ___ a federal republic.","options":["are","were","have been","is"],"answer":3,"explanation":"The name of a country is singular even when it has a plural form: 'The United States is ...'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-164","question":"Fill in the blank: He was elected ___ chairman of the board last week.","options":["no article","a","an","the"],"answer":0,"explanation":"After verbs like 'elect', 'appoint' or 'make', a title or unique post usually takes no article: 'He was elected chairman'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-165","question":"Choose the correct question tag: Few people know the real story, ___?","options":["do they","don't they","doesn't it","did they"],"answer":0,"explanation":"'Few' (without 'a') is negative in meaning ('hardly any'), so the tag is positive: 'do they?'. 'A few people know ...' would take 'don't they?'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-166","question":"Choose the correct question tag: There is hardly any milk left, ___?","options":["isn't there","is it","is there","isn't it"],"answer":2,"explanation":"'Hardly' makes the statement negative, so the tag is positive; with 'there is' the tag repeats 'there': 'is there?'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-167","question":"Fill in the blank: I'd rather you ___ tomorrow instead of today.","options":["had come","come","will come","came"],"answer":3,"explanation":"'Would rather' + a different subject takes the past (subjunctive) form to refer to the present or future: 'I'd rather you came tomorrow'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-168","question":"Change into the passive voice: He made her dance.","options":["She was being made to dance by him.","She was made dance by him.","She was made to dance by him.","She made to dance by him."],"answer":2,"explanation":"In the active, 'make' takes a bare infinitive ('made her dance'), but in the passive 'to' returns: 'She was made to dance by him'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-169","question":"Change into the passive voice: Who is calling me?","options":["By whom am I called?","By whom am I being called?","Who am I being called by him?","By whom I am being called?"],"answer":1,"explanation":"The present continuous passive is 'am/is/are being + V3', and in a question the auxiliary comes before the subject: 'By whom am I being called?'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-170","question":"Change into the passive voice: It is time to close the shop.","options":["It is time for the shop to be closed.","It is time the shop was closing.","The shop is time to be closed by them.","It is time to be closed the shop."],"answer":0,"explanation":"The active infinitive 'to close' becomes the passive infinitive 'to be closed', with the object introduced by 'for': 'It is time for the shop to be closed'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-171","question":"Change into indirect speech: The old woman said, “May God bless you, my son!”","options":["The old woman said that God may bless you, my son.","The old woman prayed that God might bless her son.","The old woman prayed to her son that God bless him.","The old woman wished that may God bless her son."],"answer":1,"explanation":"A wish or prayer with 'May' is reported with 'prayed/wished that', 'may' becomes 'might', and the vocative 'my son' is absorbed: 'prayed that God might bless her son'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-172","question":"Change into indirect speech: He said to me, “Where have you been all these days?”","options":["He told me where I have been all those days.","He asked me where had I been all these days.","He asked me where I had been all those days.","He asked me where I was all these days."],"answer":2,"explanation":"Question → 'asked'; statement word order; present perfect → past perfect ('had been'); 'these' → 'those'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-173","question":"Improve the sentence: She not only plays the piano but also the guitar.","options":["No improvement","She not only plays the piano but also plays guitar also.","Not only she plays the piano but also the guitar.","She plays not only the piano but also the guitar."],"answer":3,"explanation":"Correlatives must join parallel parts. 'The piano' and 'the guitar' are both objects of 'plays', so 'not only' should come just before 'the piano'. 'Not only she plays' would need inversion ('Not only does she play').","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-174","question":"Fill in the blank: If he had taken the medicine yesterday, he ___ better now.","options":["would be feeling","would have felt","will be feeling","had been feeling"],"answer":0,"explanation":"This is a mixed conditional: a past condition ('had taken ... yesterday') with a present result ('now'), so the main clause takes 'would + verb'. 'Would have felt' refers to the past and clashes with 'now'; 'will be feeling' ignores the unreal past condition.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-175","question":"Spot the error: The quality of the mangoes (a) / supplied by these vendors (b) / are not up to the mark. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"The head of the subject is “quality” (singular); “of the mangoes supplied by these vendors” is only a modifier, so the verb must be “is not up to the mark”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-176","question":"Fill in the blank: Scarcely had the auditors begun their inspection when the cashier ___.","options":["had absconded","absconded","has absconded","absconds"],"answer":1,"explanation":"In “Scarcely had … when …” the first action is in the past perfect and the second, which follows it, is in the simple past: “when the cashier absconded”. “Had absconded” would put his flight before the inspection.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-177","question":"Fill in the blank: Had the monsoon not failed last year, the farmers ___ in such heavy debt today.","options":["would not have been","will not be","had not been","would not be"],"answer":3,"explanation":"This is a mixed conditional: an unreal past condition (had not failed) with a present result (today), so the result clause takes “would + base verb”: would not be. “Would not have been” would refer to a past result and clash with “today”.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-grammar-178","question":"Fill in the blank: The jury ___ unable to agree among themselves, so the judge had to discharge them.","options":["was","has been","is","were"],"answer":3,"explanation":"“Among themselves” and “them” show the jury is being thought of as separate individuals who disagree, so the collective noun takes a plural verb: were. “Was” would clash with the plural pronouns.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-179","question":"Fill in the blanks: The new export policy is conducive ___ growth, but it is also fraught ___ risk.","options":["for; with","to; of","for; by","to; with"],"answer":3,"explanation":"The fixed prepositions are “conducive to” and “fraught with”. “Conducive for” and “fraught of” are common learner errors.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-180","question":"Fill in the blanks: The deal fell ___ at the last minute because the bank backed ___ of its promise to fund the project.","options":["through; out","apart; off","through; down","off; out"],"answer":0,"explanation":"A plan that fails to happen “falls through”, and to withdraw from a commitment is to “back out of” it. “Back down” is followed by “from”, not “of”, and “back off” does not take “of” in standard use.","difficulty":"hard","source":"IBPS PO Mains · CAT"},
  {"id":"eng-grammar-181","question":"Fill in the blanks: The number of applicants who ___ cleared the preliminary round ___ doubled this year.","options":["has; have","have; have","have; has","has; has"],"answer":2,"explanation":"Inside the relative clause, “who” stands for “applicants” (plural), so “who have cleared”; the main subject is “the number”, which is singular, so “has doubled”.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-182","question":"Fill in the blank: By the time you reach Pune tomorrow evening, we ___ for Goa.","options":["will leave","would have left","would leave","will have left"],"answer":3,"explanation":"An action that will be complete before a stated future moment (by the time you reach) takes the future perfect: will have left. 'Would have left' is conditional and does not fit a definite plan.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-183","question":"Fill in the blank: It is high time the government ___ firm steps to curb food inflation.","options":["took","takes","has taken","would take"],"answer":0,"explanation":"“It is high time” is followed by the past subjunctive (past form with present meaning) to show the action is overdue: took.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-184","question":"Improve the bracketed part: The reason why he resigned [was because he was overworked].","options":["was due to he was overworked","was that he was overworked","was because of being overworked","No improvement"],"answer":1,"explanation":"“The reason … was because” repeats the idea of cause; the noun “reason” is completed by a that-clause: “The reason was that he was overworked.”","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-grammar-185","question":"Spot the error: Unless you do not submit (a) / the form by Friday, (b) / your claim will lapse. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"“Unless” already means “if not”, so adding “do not” makes a double negative: “Unless you submit the form by Friday …”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-186","question":"Fill in the blank: Walk carefully on the wet floor lest you ___.","options":["should not slip","will slip","should slip","would not slip"],"answer":2,"explanation":"“Lest” means “for fear that” and already carries the negative idea; it is followed by “should + base verb” (or the bare subjunctive), never by “not” or “will”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-187","question":"Spot the error: The selection committee comprises of (a) / five eminent scientists (b) / and two senior administrators. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"“Comprise” is transitive and takes no preposition: the committee comprises five scientists (or “consists of” five scientists).","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-188","question":"Spot the error: I look forward (a) / to meet you (b) / at the conference next month. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"In “look forward to”, “to” is a preposition, so it is followed by a gerund: “to meeting you”.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-189","question":"Fill in the blank: Not only ___ the entrance exam, but he also topped the state merit list.","options":["he cleared","cleared he","he did clear","did he clear"],"answer":3,"explanation":"When a sentence opens with “Not only”, the clause takes question-style inversion with an auxiliary: “Not only did he clear …”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-190","question":"Fill in the blank: Ten kilometres ___ too long a distance to walk in this heat.","options":["are","were","is","have been"],"answer":2,"explanation":"A plural amount of distance, money or time thought of as one quantity takes a singular verb: “Ten kilometres is too long a distance”.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-191","question":"Fill in the blank: She ___ in the firm for six years when it was taken over by a rival group.","options":["has been working","was working","worked","had been working"],"answer":3,"explanation":"An action continuing up to a past point (the takeover), with its duration stated, takes the past perfect continuous: had been working.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-192","question":"Fill in the blank: ___ you need any assistance during your stay, please contact the front desk.","options":["Would","Unless","Were","Should"],"answer":3,"explanation":"“Should you need …” is the inverted form of “If you should need …” for a possible future situation. “Were” would need “to” (Were you to need), and “Had” fits only past conditions.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-193","question":"Fill in the blanks: The firm hired ___ European designer and ___ MBA graduate from Pune.","options":["a; an","an; an","an; a","a; a"],"answer":0,"explanation":"Articles follow sound, not spelling: “European” begins with a /j/ (yoo) sound, so “a European”; “MBA” is read “em-bee-ay”, beginning with a vowel sound, so “an MBA”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-194","question":"Choose the correct indirect speech: He said, “I would rather starve than beg.”","options":["He said that he would rather have starved than begged.","He said that he had rather starve than beg.","He said that he would rather starve than beg.","He said that he would rather starve than to beg."],"answer":2,"explanation":"“Would” does not change in reported speech, and “would rather … than” takes the bare infinitive on both sides: would rather starve than beg.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-195","question":"Choose the correct passive form: People believe that he was killed in the riots.","options":["He is believed to have been killed in the riots.","He is believed to be killed in the riots.","He was believed to have been killed in the riots.","He was believed to be killed in the riots."],"answer":0,"explanation":"The belief is present (is believed) and the killing is earlier and passive, so the perfect passive infinitive is needed: “to have been killed”. “Was believed” wrongly shifts the belief into the past.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-196","question":"Spot the error: I prefer (a) / to resign than (b) / to compromise on my principles. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"“Prefer” with infinitives is followed by “rather than”, not “than”: “I prefer to resign rather than compromise.” (With nouns or gerunds it takes “to”: prefer resigning to compromising.)","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-grammar-197","question":"Spot the error: His monthly salary is much higher (a) / than a clerk (b) / working in the same department. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"Like must be compared with like: his salary with a clerk's salary, not with a clerk. Correct: “than that of a clerk”.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-198","question":"Fill in the blank: After a two-year trial, the accused was acquitted ___ the charge of forgery.","options":["from","for","with","of"],"answer":3,"explanation":"One is “acquitted of” a charge (just as one is “accused of” or “convicted of” it). “Acquitted from” is a common error.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-199","question":"Spot the error: The doctor advised him (a) / to abstain to (b) / spicy and oily food. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"“Abstain” takes “from”: to abstain from spicy and oily food. “Abstain to” is a confusion with “refrain/object to”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-200","question":"Spot the error: Having worked night shifts for years, I am used to (a) / work late (b) / on Fridays. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"In “be used to” (be accustomed to), “to” is a preposition and needs a gerund: “I am used to working late”. “Used to work” (without “am”) would mean a past habit.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-201","question":"Spot the error: The man (a) / who I thought was my friend (b) / betrayed me in the end. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":3,"explanation":"“I thought” is only a parenthetical insertion; “who” is the subject of “was” (who was my friend), so the nominative “who” is correct and the sentence has no error. Changing it to “whom” is the trap.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-grammar-202","question":"Fill in the blank: A great many students ___ failed to submit the assignment on time.","options":["have","has","were","was"],"answer":0,"explanation":"“A great many” is followed by a plural noun and a plural verb: “A great many students have failed”. Do not confuse it with “Many a student has”; 'were failed' wrongly makes it passive.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-203","question":"Spot the error: In the early morning (a) / the jasmine in our garden (b) / smells very sweetly. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"“Smell” here is a linking verb describing the subject, so it takes an adjective complement, not an adverb: “smells very sweet”.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-204","question":"Fill in the blank: By the time we reached the platform, the Rajdhani ___.","options":["left","has left","had left","was leaving"],"answer":2,"explanation":"Of two past actions, the one completed first (the train's departure) takes the past perfect when “by the time” marks the later one: had left.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-205","question":"Spot the error: There was hardly (a) / no water left (b) / in the tank by noon. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"“Hardly” is already negative in meaning, so it must not be combined with “no”: “There was hardly any water left”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-206","question":"Fill in the blank: I wish I ___ the job offer last year; I would be living in Mumbai now.","options":["accepted","would accept","have accepted","had accepted"],"answer":3,"explanation":"A wish about the past (last year) takes the past perfect: “I wish I had accepted”. The simple past after “wish” refers to the present.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-207","question":"Fill in the blank: Though he is only a clerk, he talks as if he ___ the owner of the company.","options":["were","is","has been","will be"],"answer":0,"explanation":"“As if” introducing something contrary to fact (he is not the owner) takes the past subjunctive: “as if he were the owner”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-208","question":"Fill in the blank: A cautious investor by nature, she is averse ___ taking unnecessary risks.","options":["from","of","to","against"],"answer":2,"explanation":"“Averse” takes “to” (like “opposed to”); “averse from” and “averse of” are learner errors, and the following verb becomes a gerund.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-209","question":"Fill in the blanks: The minister was accused ___ corruption and later charged ___ fraud.","options":["for; with","of; for","of; with","with; of"],"answer":2,"explanation":"The fixed patterns are “accused of” a wrong and “charged with” an offence. “Charged for” refers to a price, not an offence.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-210","question":"Spot the error: He is the candidate (a) / whom I think (b) / deserves the award. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"Remove the parenthetical “I think” and the clause reads “… deserves the award”, so the pronoun is the subject of “deserves” and must be “who”, not “whom”.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-grammar-211","question":"Spot the error: The cattle is grazing (a) / in the field (b) / behind the school. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"“Cattle” is a plural noun without an -s (like “police” and “people”), so it takes a plural verb: “The cattle are grazing”.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-212","question":"Fill in the blank: Only after the forensic audit ___ the true scale of the fraud.","options":["the board realised","realised the board","the board did realise","did the board realise"],"answer":3,"explanation":"A sentence that opens with “Only after …” takes inversion in the main clause, with an auxiliary before the subject: “did the board realise”.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-213","question":"Fill in the blank: So engrossed ___ in the novel that she missed her station.","options":["she was","had she","was she","she has been"],"answer":2,"explanation":"Fronting “So + adjective” for emphasis requires inversion of the verb and subject: “So engrossed was she … that …”. “Had she” has no matching participle.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-214","question":"Improve the bracketed part: The more you practise, [more confident you become].","options":["the more confidently you become","the more confident you become","more confident you will become","No improvement"],"answer":1,"explanation":"The comparative correlative needs “the” in both halves: “The more …, the more confident …”. “Become” is a linking verb, so it takes the adjective “confident”, not the adverb.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-215","question":"Improve the bracketed part: He visits the temple every Sunday, [isn't it]?","options":["doesn't he","isn't he","does he","No improvement"],"answer":0,"explanation":"A question tag repeats the auxiliary and subject of the main clause: a positive simple-present “He visits” takes the negative tag “doesn't he?”. “Isn't it” is a common Indian-English error.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-216","question":"Spot the error: Despite of (a) / repeated warnings from his doctor, (b) / he continued to smoke. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"“Despite” is itself a preposition and takes no “of”; use “Despite repeated warnings” or “In spite of repeated warnings”.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-217","question":"Spot the error: The house (a) / whose roof is leaking (b) / belongs to my uncle. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":3,"explanation":"“Whose” is the standard possessive relative for things as well as people (“of which” is only a more formal option), so the sentence has no error.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-grammar-218","question":"Spot the error: Of the two brothers, (a) / Ajay is the tallest (b) / and also the more athletic. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"When only two are compared, the comparative is used: “Ajay is the taller”. Part (c) already uses the correct comparative “the more athletic”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-219","question":"Spot the error: Nobody except he (a) / knew the combination (b) / to the safe. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"“Except” is a preposition, so the pronoun after it takes the objective case: “Nobody except him knew …”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-220","question":"Spot the error: We watched the documentary twice (a) / because it was (b) / so interested. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"The -ing adjective describes what causes the feeling and the -ed adjective describes the person who feels it: the documentary was “interesting”; we were “interested”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-221","question":"Fill in the blank: If the bridge had been inspected in time, the accident ___.","options":["could be averted","will have been averted","would avert","could have been averted"],"answer":3,"explanation":"A third conditional (had been inspected) needs a perfect modal in the result clause, and the accident is acted upon, so it is passive: could have been averted.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-222","question":"Spot the error: He flatly denied to have taken (a) / the money (b) / from the drawer. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"“Deny” is followed by a gerund, not an infinitive: “denied having taken (or taking) the money”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-223","question":"Spot the error: The counsellor suggested (a) / me to apply (b) / for the scholarship. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"“Suggest” does not take the object + to-infinitive pattern; use “suggested that I (should) apply” or “suggested my applying”.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-224","question":"Spot the error: It is I (a) / who am responsible (b) / for this mess. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":3,"explanation":"After “It is”, the formal nominative “I” is correct, and the verb in the relative clause agrees with the antecedent of “who”, which is “I”: “who am responsible”. There is no error.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-grammar-225","question":"Spot the error: My uncle, (a) / who lives in London, (b) / he is a doctor. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"The subject “My uncle” is already stated; repeating it as “he” after the relative clause gives the verb two subjects. Correct: “My uncle, who lives in London, is a doctor.”","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-226","question":"Spot the error: The injured cyclist (a) / was laying (b) / on the road for an hour. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"“Lay” (laid, laying) is transitive and needs an object; to be in a horizontal position is “lie” (lay, lain, lying): “was lying on the road”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-227","question":"Spot the error: The curator hanged (a) / the portrait (b) / in the main gallery. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"“Hanged” is used only for execution by hanging; for pictures and objects the past tense is “hung”: “The curator hung the portrait”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-228","question":"Spot the error: For Hindus, the Ganga is (a) / holiest river (b) / of India. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"A superlative adjective before a noun takes the definite article: “the holiest river of India”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-229","question":"Fill in the blank: ___ students passed the surprise test, so the teacher was disappointed.","options":["A few","The few","Little","Few"],"answer":3,"explanation":"“Few” (without “a”) means “hardly any” and carries the negative sense that explains the disappointment; “a few” means “some” and is positive. “Little” is for uncountable nouns.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-230","question":"Spot the error: I have less friends (a) / in this city (b) / than my brother has. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"“Less” is used with uncountable nouns; with countable plurals like “friends” use “fewer”: “I have fewer friends”.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-231","question":"Spot the error: Though he worked hard, (a) / yet he could not (b) / clear the exam. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":3,"explanation":"“Though … yet” is an accepted correlative pair (it is “though … but” that is wrong), so this sentence has no error.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-232","question":"Spot the error: The workers demanded (a) / that their wages (b) / are raised immediately. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"After verbs of demand, insistence or proposal, the that-clause takes the subjunctive (or “should”): “that their wages be raised (or should be raised)”.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-233","question":"Fill in the blank: He was born ___ the morning of 15 August 1990.","options":["in","at","on","during"],"answer":2,"explanation":"“In the morning” is general, but once the morning is tied to a specific date it becomes a particular day-part and takes “on”: on the morning of 15 August.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-234","question":"Spot the error: She is married (a) / with a doctor (b) / from Lucknow. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"The idiom is “married to” someone: “She is married to a doctor”. “Married with” is used only as in “married with two children”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-235","question":"Spot the error: The board will (a) / discuss about (b) / the merger tomorrow. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"“Discuss” is transitive and takes a direct object: “discuss the merger”. The noun takes the preposition (a discussion about), the verb does not.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-236","question":"Fill in the blanks: The meeting was put ___ until next week because the chairman was down ___ flu.","options":["out; with","off; by","up; with","off; with"],"answer":3,"explanation":"To postpone is to “put off”, and to be ill with something is to be “down with” it. “Put out” means to extinguish or inconvenience; “put up” means to raise or lodge.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-237","question":"Fill in the blank: The old roof finally gave ___ under the weight of the snow.","options":["in","up","off","way"],"answer":3,"explanation":"A structure that collapses under pressure “gives way”. “Give in” and “give up” are used of people yielding or quitting, and “give off” means to emit.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-238","question":"Fill in the blank: In her fierce independence, she takes ___ her mother.","options":["to","over","along","after"],"answer":3,"explanation":"To resemble a parent or older relative in character or looks is to “take after” them. “Take to” means to begin to like, and “take over” means to assume control.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-239","question":"Spot the error: She bought (a) / three dozens bananas (b) / from the market. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"After a definite number, “dozen” (like hundred, thousand) stays singular: “three dozen bananas”. “Dozens of” is used only without a number.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-240","question":"Spot the error: The ten-years-old boy (a) / solved the puzzle (b) / in two minutes. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"In a hyphenated compound adjective before a noun, the noun of measure stays singular: “a ten-year-old boy” (but “the boy is ten years old”).","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-241","question":"Spot the error: I will call you (a) / as soon as (b) / I will reach home. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"In time clauses introduced by when, as soon as, before, after or until, the simple present expresses the future: “as soon as I reach home”.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-242","question":"Choose the correct indirect speech: He said to us, “Let us wait for the next bus.”","options":["He suggested to us that we should wait for the next bus.","He told us that let us wait for the next bus.","He suggested us to wait for the next bus.","He told us that we will wait for the next bus together."],"answer":0,"explanation":"“Let us” expressing a proposal is reported with “suggested/proposed (to us) that we should …”. “Suggested us to” is ungrammatical, and “will” fails to backshift.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-243","question":"Spot the error: The passenger (a) / who's bag was stolen (b) / complained to the conductor. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"“Who's” is the contraction of “who is/who has”; the possessive relative pronoun is “whose”: “whose bag was stolen”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-244","question":"Spot the error: Please wait here (a) / till I do not return (b) / from the bank. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"“Till/until” already sets the limit of the waiting, so the negative is wrong: “wait here till I return”. This is a common Hindi-influenced error.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-245","question":"Spot the error: Ramesh's (a) / and Suresh's shop (b) / is in the old market. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"For one jointly owned thing, only the last name takes the apostrophe: “Ramesh and Suresh's shop”. “Ramesh's and Suresh's” would imply two separate shops and need the plural “shops are”.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-grammar-246","question":"Spot the error: Had I known (a) / about the strike, (b) / I would not come. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"“Had I known” is an inverted third conditional (unreal past), so the result clause needs “would + have + past participle”: “I would not have come”.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-247","question":"Spot the error: Ninety per cent (a) / of the work (b) / have been completed. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"With percentages and fractions, the verb agrees with the noun after “of”; “work” is uncountable and singular, so “has been completed”.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-248","question":"Fill in the blank: The government has decided to do ___ with the outdated licensing rules.","options":["off","out","over","away"],"answer":3,"explanation":"To abolish or get rid of something is to “do away with” it. “Do up” means to fasten or renovate, and “do off/out/over with” are not standard phrasal verbs.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-249","question":"Fill in the blank: Unless the strike ___ off by Monday, the exams will be postponed.","options":["is called","will be called","was called","calls"],"answer":0,"explanation":"A conditional clause about the future (unless = if not) takes the present tense, and the strike is called off by someone, so it is passive: “is called off”.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-250","question":"Fill in the blank: ‘The Arabian Nights’ ___ still popular with children all over the world.","options":["are","were","is","have been"],"answer":2,"explanation":"The title of a book is a single work, so it takes a singular verb even if it looks plural: “‘The Arabian Nights’ is still popular”.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-251","question":"The panel insisted that the minister ___ the allegations in person before the committee.","options":["answers","answered","would answer","answer"],"answer":3,"explanation":"After 'insist that' (a demand), standard formal English uses the subjunctive: the bare verb 'answer' for every subject. 'Answers' is the trap, copying the third-person singular 'minister'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-252","question":"It is high time the department ___ its outdated record-keeping system.","options":["replaced","has replaced","would replace","replaces"],"answer":0,"explanation":"'It is (high) time' + subject takes the simple past form (replaced) to show that the action is overdue, though the sense is present. The present and perfect forms do not follow this fixed pattern.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-253","question":"Spot the error: No sooner did the chairman rise to speak (a) / when the hall (b) / erupted in protest. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"'No sooner' is paired with 'than', never with 'when' ('hardly/scarcely' take 'when'). So part (b) should begin 'than'. The inversion 'did the chairman rise' in (a) is correct.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-254","question":"Improve the bracketed part: Reading the notice carefully, [the error was noticed by Meena] at once.","options":["the error noticed Meena","it was Meena the error noticed","Meena noticed the error","No improvement"],"answer":2,"explanation":"The opening participle 'Reading' must modify the subject of the main clause. In the passive version the subject is 'the error', which cannot read, so the modifier dangles. 'Meena noticed' fixes it.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-255","question":"Even now, neither the manager nor his assistants ___ aware of the leak.","options":["was","has been","is","are"],"answer":3,"explanation":"With 'neither...nor', the verb agrees with the nearer subject, 'assistants' (plural). 'Even now' fixes the present tense, which rules out 'was'; 'is' and 'has been' are singular.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-256","question":"He is one of those officers who ___ never late for a meeting.","options":["are","has been","is","was"],"answer":0,"explanation":"In 'one of those ... who', the relative pronoun 'who' refers to the plural 'officers', so the verb is plural: 'are'. The trap is to agree with 'one'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-257","question":"Spot the error: The climate of Shimla (a) / is much cooler (b) / than Chennai. (c) / No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"Two climates must be compared, not a climate and a city. Part (c) should read 'than that of Chennai'. 'Much cooler' is a correct comparative with an intensifier.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-258","question":"Spot the error: I prefer to walk (a) / to the market (b) / than to take a rickshaw. (c) / No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"'Prefer' takes 'to' with nouns or gerunds (prefer walking to riding); with infinitives it needs 'rather than'. So (c) should read 'rather than take a rickshaw'; 'than' alone after 'prefer' is wrong.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-259","question":"Had it not been for her timely intervention, the project ___.","options":["will have collapsed","would have collapsed","would collapse","had collapsed"],"answer":1,"explanation":"The inverted 'Had it not been for' is a third conditional (past unreal), so the main clause needs 'would have' + past participle. 'Would collapse' belongs to a second conditional.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-260","question":"Choose the correct indirect speech: She said, \"Alas! I have lost my only photograph.\"","options":["She exclaimed sadly that she has lost her only photograph.","She said sadly that she lost his only photograph.","She said that alas she has lost her only photograph.","She exclaimed sadly that she had lost her only photograph."],"answer":3,"explanation":"The interjection 'Alas' is rendered by 'exclaimed sadly', the present perfect shifts to the past perfect ('had lost') after a past reporting verb, and 'my' becomes 'her'.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-261","question":"Spot the error: The teacher told the class (a) / that the earth moved (b) / round the sun. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"A universal truth stays in the present tense even after a past reporting verb, so (b) should read 'the earth moves'. The back-shift rule does not apply here.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-262","question":"Not until the results were declared ___ the mistake in the question paper.","options":["did he realise","had he realised","he realised","he did realise"],"answer":0,"explanation":"A sentence that begins with 'Not until ...' takes auxiliary-subject inversion in the main clause: 'did he realise'. The simple past in the 'until' clause rules out 'had he realised'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-263","question":"Spot the error: The jury has announced its verdict (a) / although its members (b) / is still divided (c) / on the sentence. No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"'Its members' is a plural subject, so (c) should read 'are still divided'. Using 'its' for the jury as a unit is fine; the verb must agree with 'members'.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-264","question":"The number of unemployed graduates ___ risen sharply, and a number of them ___ turned to freelancing.","options":["has; has","has; have","have; have","have; has"],"answer":1,"explanation":"'The number of' is singular ('has'), while 'a number of' means 'several' and is plural ('have'). Swapping them is the classic trap.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-265","question":"Spot the error: He insisted (a) / on me (b) / paying the bill. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"Before a gerund used as a noun, standard exam usage prefers the possessive: 'insisted on my paying'. So (b) is the error.","difficulty":"very-hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-266","question":"Spot the error: She has been suffering (a) / from fever (b) / since last four days. (c) / No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"'Since' needs a point of time; a stretch of days takes 'for': 'for the last four days'. So (c) is wrong.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-267","question":"The auditor was dissuaded ___ revealing the figures by the threat of a lawsuit.","options":["against","of","to","from"],"answer":3,"explanation":"'Dissuade' takes 'from' + gerund (dissuade someone from doing); its opposite 'persuade' takes 'to'. Learners pick 'to' by mirroring 'persuade'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-268","question":"The manager, together with his two deputies, ___ expected at the airport.","options":["is","have been","are","were"],"answer":0,"explanation":"'Together with' does not make the subject plural; the verb agrees with 'manager', so the singular 'is' is right. 'Are' is pulled by the nearby 'deputies'.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-269","question":"Improve the bracketed part: She is the only one of the students [who have scored full marks].","options":["who has scored full marks","who were scoring full marks","which have scored full marks","No improvement"],"answer":0,"explanation":"With 'the only one of the ...', the relative pronoun refers to 'one' (not the plural 'students'), so the verb is singular: 'has scored'. 'Which' cannot refer to a person.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-270","question":"Improve the bracketed part: [Scarcely he had entered] the room when the lights went out.","options":["Scarcely he entered","Scarcely did he enter","Scarcely had he entered","No improvement"],"answer":2,"explanation":"'Scarcely' at the start of a clause forces inversion with the past perfect: 'Scarcely had he entered ... when'. Without inversion the sentence is ungrammatical.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-271","question":"Spot the error: Two-thirds of the village (a) / was destroyed (b) / by the flood. (c) / No error (d)","options":["a","b","c","d"],"answer":3,"explanation":"With a fraction + 'of' + singular noun ('village') the verb is singular, so 'was destroyed' is correct. The sentence has no error; a plural noun would have required 'were'.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-272","question":"Should anyone call while I am away, ___ them that I will return on Monday.","options":["telling","tell","told","will tell"],"answer":1,"explanation":"The 'Should ... call' clause is a conditional, and the result clause here is a plain imperative: 'tell them'. A future 'will tell' would change the speaker, not the instruction.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-273","question":"Spot the error: He is a (a) / M.B.A. from (b) / a reputed institute. (c) / No error (d)","options":["a","b","c","d"],"answer":0,"explanation":"The choice of 'a' or 'an' depends on sound: M is pronounced 'em', which begins with a vowel sound, so 'an M.B.A.' is correct. Part (a) is wrong.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-274","question":"Spot the error: The accused, (a) / who was found guilty, (b) / was sentenced for (c) / ten years' imprisonment. No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"One is sentenced 'to' a punishment, and 'for' a crime. So (c) should read 'sentenced to ten years' imprisonment'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-275","question":"Everyone except the two clerks ___ the notice by now.","options":["have read","were reading","are read","has read"],"answer":3,"explanation":"'Everyone' is singular, and 'except the two clerks' is only a prepositional phrase that does not change the number. The sentence needs 'has read'.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-276","question":"Spot the error: The Principal as well as the teachers (a) / were present (b) / at the annual function. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"'As well as' is not a conjunction like 'and'; the verb agrees with the first subject, 'Principal', so (b) should read 'was present'.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-277","question":"He behaves as though he ___ the only person who knew the answer.","options":["were","has been","will be","is"],"answer":0,"explanation":"'As though' introducing an unreal comparison takes the subjunctive 'were'. 'Is' would present the claim as a fact.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-278","question":"Spot the error: The luggage (a) / which were left behind (b) / has been traced by the airline. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"'Luggage' is an uncountable noun and takes a singular verb, so the relative clause should read 'which was left behind'. The main verb 'has been traced' in (c) is already correct.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-279","question":"The accident left him with ___ injuries that he could not walk for a year.","options":["so serious","too serious","very serious","such serious"],"answer":3,"explanation":"Before an adjective + plural noun, 'such' is used ('such serious injuries'); 'so' goes directly with an adjective ('so serious'). The 'that' clause needs this result pattern.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-280","question":"Improve the bracketed part: The old man is [too weak that he cannot walk] without a stick.","options":["so weak that he cannot walk","too weak so that he cannot walk","very weak for he cannot walk","No improvement"],"answer":0,"explanation":"The result pattern is 'so + adjective + that'. 'Too' already carries a negative sense ('too weak to walk') and never takes a 'that' clause with 'cannot'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-281","question":"Spot the error: Unless you do not (a) / apologise to the manager, (b) / he will not forgive you. (c) / No error (d)","options":["a","b","c","d"],"answer":0,"explanation":"'Unless' already means 'if ... not', so adding 'not' creates a double negative. Part (a) should read 'Unless you apologise'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-282","question":"If it ___ rain tomorrow, the match will be postponed to Sunday.","options":["should","will","would","shall"],"answer":0,"explanation":"'If it should rain' is the correct way to express a less likely future condition after 'if'. 'Will' and 'would' are not used in the 'if' clause, and 'shall' does not suit a third-person subject.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-283","question":"Spot the error: Having been told the news, (a) / he rushed (b) / out the room. (c) / No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"'Out' used as a preposition needs 'of' before the noun: 'rushed out of the room'. The participial phrase in (a) correctly modifies 'he'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-284","question":"The new manager is very conscious ___ the importance of punctuality.","options":["with","about","of","for"],"answer":2,"explanation":"'Conscious' takes 'of'. 'Aware' also takes 'of', and the mistake with 'about' is tempting after 'concerned about'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-285","question":"Spot the error: His parents, (a) / both of whom are doctors, (b) / lives in Pune. (c) / No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"The subject is 'parents' (plural). The relative clause between commas is only extra information, so (c) should read 'live in Pune'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-286","question":"The jury ___ unable to agree, the judge ordered a retrial.","options":["were","having","was","being"],"answer":3,"explanation":"The sentence has two clauses with different subjects, so the first needs a participle in an absolute construction: 'The jury being unable to agree'. 'Was' or 'were' would join two full clauses with only a comma.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-287","question":"Spot the error: Not only did he lose the money (a) / but he also (b) / lost his reputation. (c) / No error (d)","options":["a","b","c","d"],"answer":3,"explanation":"'Not only' at the start takes inversion in the first clause ('did he lose'), and the second clause after 'but also' is a normal past ('lost'). The sentence is correct.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-288","question":"Spot the error: The Ramayana (a) / are one of (b) / the great epics of India. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"'The Ramayana' is a single work, so the verb must be singular: 'is one of'. 'Epics' is only the object of 'of' and does not decide agreement.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-289","question":"Improve the bracketed part: The student [who's essay won the first prize] has been invited to the ceremony.","options":["whom essay won the first prize","which essay won the first prize","whose essay won the first prize","No improvement"],"answer":2,"explanation":"The possessive 'whose' is needed, since the essay belongs to the student. 'Who's' is only the contraction of 'who is' or 'who has'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-290","question":"Improve the bracketed part: The new recruit is intelligent, hardworking and [has a great sense of humour].","options":["humorous","a great humorous person","she has a great deal of humour","having a great sense of humour"],"answer":0,"explanation":"The three qualities must be parallel in form, and the first two are adjectives, so the third must be an adjective too: 'humorous'. The other options break the parallel structure.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-291","question":"He neither wrote to me nor ___ me, even after I had left three messages.","options":["did he telephone","has telephoned","telephoned","telephones"],"answer":2,"explanation":"After 'neither ... nor', the two parts must have the same grammatical form. 'Wrote' is a simple past verb, so the part after 'nor' must also be simple past: 'telephoned'. Inversion would break the parallelism.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-292","question":"Choose the correct indirect speech: He said to her, \"Why are you crying?\"","options":["He told her why she was crying.","He asked her that why she cried.","He asked her why was she crying.","He asked her why she was crying."],"answer":3,"explanation":"A wh-question becomes a statement in reported speech, with no inversion: 'why she was crying'. The reporting verb is 'asked' and the present continuous shifts to the past continuous.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-293","question":"Choose the correct indirect speech: The teacher said to the boy, \"Do not make a noise.\"","options":["The teacher ordered the boy not to make a noise.","The teacher ordered the boy to not made a noise.","The teacher advised the boy do not make a noise.","The teacher ordered the boy that not to make a noise."],"answer":0,"explanation":"A negative imperative is reported with 'not to' + infinitive after an ordering verb ('ordered', 'told', 'forbade'). The other options mix in wrong verb forms or an extra 'that'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-294","question":"I cannot help ___ that she was right all along, much as I dislike admitting it.","options":["to think","thinking","think","thought"],"answer":1,"explanation":"'Cannot help' takes a gerund when it means 'cannot avoid': 'cannot help thinking'. The bare infinitive follows 'cannot help but', not 'cannot help'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-295","question":"Spot the error: It is no use (a) / to cry (b) / over spilt milk. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"'It is no use' (and 'it is no good') is followed by a gerund: 'crying over spilt milk'. The infinitive in (b) is the error.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-296","question":"By next March, the company ___ in this city for fifty years.","options":["would operate","has been operating","will have been operating","is operating"],"answer":2,"explanation":"A time marker looking ahead ('By next March') combined with a duration ('for fifty years') calls for the future perfect continuous: 'will have been operating'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-297","question":"Spot the error: The manager asked (a) / that who had (b) / opened the confidential file. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"A reported wh-question uses the wh-word directly after the reporting verb, with no 'that': 'asked who had opened'. So (b) is the error.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-298","question":"Of the two sisters, Meera is ___ and more careful with money.","options":["wisest","most wise","the wisest","the wiser"],"answer":3,"explanation":"For two persons, the comparative with 'the' is used: 'the wiser'. Superlatives like 'wisest' and 'most wise' are for three or more.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-299","question":"Spot the error: The data (a) / are being analysed (b) / by two independent teams. (c) / No error (d)","options":["a","b","c","d"],"answer":3,"explanation":"'Data' is the plural of 'datum' and, in careful exam usage, takes a plural verb. 'Are being analysed' is therefore correct and the sentence has no error.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-300","question":"The two parties finally ___ at an agreement after weeks of negotiation.","options":["arrived","reached","came","got"],"answer":0,"explanation":"'Arrive at' is followed by a preposition, so 'arrived at an agreement' fits. 'Reach' is a transitive verb that takes no preposition ('reached an agreement'), so the 'at' in the sentence rules it out.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-301","question":"Spot the error: The committee have (a) / submitted its report (b) / to the chairman. (c) / No error (d)","options":["a","b","c","d"],"answer":0,"explanation":"The same collective noun must be treated consistently. Since the pronoun 'its' treats the committee as a single unit, the verb must be singular too: 'The committee has submitted its report'.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-302","question":"Had the witness not turned hostile, the verdict ___ different.","options":["will have been","had been","would be","would have been"],"answer":3,"explanation":"'Had the witness not turned' is an inverted third conditional referring to the unreal past, so the result clause takes 'would have been'. 'Would be' is the pattern for a present unreal condition.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-303","question":"Spot the error: One should respect (a) / his elders (b) / and obey them. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"The indefinite pronoun 'one' must be followed by 'one's' (and 'one' again) in formal usage, so (b) should read 'one's elders'. Switching to 'his' mixes the pronouns.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-304","question":"He is believed to ___ left the country a week before the raid took place.","options":["has","had","be","have"],"answer":3,"explanation":"After 'to', a perfect infinitive 'to have + past participle' shows that the leaving came before the believing. 'Has' and 'had' are finite forms and cannot follow 'to'.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-305","question":"Spot the error: She asked me (a) / if I could lend her (b) / my notes of yesterday's lecture. (c) / No error (d)","options":["a","b","c","d"],"answer":3,"explanation":"A yes-or-no question is reported with 'if' or 'whether', and the sentence reads as a question spoken the same day, so 'yesterday's' stays unchanged. The sentence has no error.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-306","question":"After twenty years of service, every employee is entitled ___ a pension.","options":["to","with","for","of"],"answer":0,"explanation":"'Entitled' always takes 'to' (entitled to a pension). The other prepositions are not used with this adjective.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-307","question":"Spot the error: The Government has (a) / appointed a committee (b) / to enquire for the matter. (c) / No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"'Enquire' and 'inquire' take 'into' when a matter is investigated, so (c) should read 'to enquire into the matter'. 'Enquire for' would mean to ask for something.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-308","question":"Improve the bracketed part: Ravi is the tallest [of any boy in the class].","options":["among any boy","than any other boy","of all the boys","No improvement"],"answer":2,"explanation":"A superlative must be followed by a plural group ('of all the boys'). 'Of any boy' mixes a superlative with a singular comparison, which needs 'taller than any other boy'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-309","question":"Spot the error: Rahul is the (a) / more intelligent (b) / of the three brothers. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"The comparative 'more' is for two persons. For three brothers the superlative is required, so (b) should read 'most intelligent'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-310","question":"She has ___ MA in history and works as ___ university lecturer.","options":["a; an","an; an","a; a","an; a"],"answer":3,"explanation":"The article depends on sound. 'MA' begins with the vowel sound 'em', so it takes 'an', while 'university' begins with the consonant sound 'yoo', so it takes 'a'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-311","question":"Spot the error: My friend and colleague, (a) / Mr. Sharma, (b) / have joined the firm. (c) / No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"'My friend and colleague' refers to one person (one article/possessive governs both nouns), so the verb is singular: 'has joined'. The commas make 'Mr. Sharma' an apposition, not a second subject.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-312","question":"Improve the bracketed part: [Being a rainy day], we stayed at home and played cards.","options":["It being a rainy day","As being a rainy day","Being it a rainy day","No improvement"],"answer":0,"explanation":"The participle 'Being' needs its own subject when it differs from the subject of the main clause. The absolute construction 'It being a rainy day' supplies it.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-313","question":"Of the two proposals, the ___ is more practical.","options":["latter","later","last","latest"],"answer":0,"explanation":"'Latter' refers to the second of two things already named. 'Later' refers to time, and 'last' and 'latest' are for more than two or for recency.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-314","question":"Spot the error: He has finished (a) / the entire work (b) / yesterday. (c) / No error (d)","options":["a","b","c","d"],"answer":0,"explanation":"A definite past time such as 'yesterday' cannot be used with the present perfect. Part (a) should read 'He finished'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-315","question":"She is looking forward to ___ her hometown after ten years.","options":["be visiting","visiting","visit","have visited"],"answer":1,"explanation":"In 'look forward to', 'to' is a preposition, so a gerund must follow: 'visiting'. A bare or perfect infinitive is the trap.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-316","question":"Because of the sudden downpour, hardly ___ guests reached the venue on time.","options":["few","a few","any","some"],"answer":2,"explanation":"'Hardly' already has a negative sense, so it combines with 'any' ('hardly any guests'). 'Few' and 'a few' would double the idea of fewness, and 'some' contradicts it.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-317","question":"Choose the correct passive voice: The committee has rejected the proposal.","options":["The proposal is being rejected by the committee.","The proposal had been rejected by the committee.","The proposal was rejected by the committee.","The proposal has been rejected by the committee."],"answer":3,"explanation":"The tense of the passive must match the active. The present perfect 'has rejected' becomes 'has been rejected'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-318","question":"Choose the correct active voice: The student was made to apologise by the principal.","options":["The principal made the student apologise.","The principal had made the student apologise.","The principal made the student to apologise.","The principal makes the student apologise."],"answer":0,"explanation":"'Was made to apologise' is simple past, so the active is 'made' + object + bare infinitive. The 'to' appears only in the passive.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-319","question":"Spot the error: Rarely (a) / he comes (b) / to the office on time. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"A sentence beginning with 'Rarely' needs inversion of the auxiliary and subject, so (b) should read 'does he come'.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-320","question":"Spot the error: The sooner (a) / you submit the form, (b) / better it is. (c) / No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"The 'the ... the ...' pattern needs 'the' in both halves. Part (c) should read 'the better it is'.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-321","question":"He was so angry that he could not but ___ the truth.","options":["admitted","admit","admitting","to admit"],"answer":1,"explanation":"'Cannot but' is followed by the bare infinitive (it means 'cannot help but admit' or 'is bound to admit'). A gerund or 'to' form is wrong after it.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-322","question":"Nobody called while you were out, ___?","options":["didn't they","did he","did they","didn't he"],"answer":2,"explanation":"'Nobody' makes the statement negative in sense, so the tag must be positive. 'Nobody' is referred to with plural 'they', hence 'did they'.","difficulty":"very-hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-323","question":"Between you and ___, the plan is bound to fail.","options":["myself","mine","I","me"],"answer":3,"explanation":"After a preposition ('between'), a pronoun must be in the objective case: 'between you and me'. 'I' is the common mistake.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-324","question":"The principal, ___ the staff feared but also respected, was in fact a kindly man.","options":["whom","which","who","whose"],"answer":0,"explanation":"The pronoun is the object of 'feared' ('the staff feared him'), so the objective 'whom' is required. 'Who' is the subject form, and 'which' cannot refer to a person.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-325","question":"Spot the error: Scarcely had the train left (a) / than the guard (b) / realised his mistake. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"'Scarcely' (like 'hardly') is paired with 'when' or 'before', not 'than'. So (b) should begin 'when the guard'. 'No sooner' is the one that takes 'than'.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-326","question":"Spot the error: The assembly passed (a) / a resolution to (b) / condemn against the attack. (c) / No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"'Condemn' is a transitive verb and takes no preposition: 'condemn the attack'. The 'against' in (c) comes from the phrase 'protest against'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-327","question":"The price of vegetables, as well as of pulses, ___ risen sharply since the floods.","options":["are","were","have","has"],"answer":3,"explanation":"'As well as of pulses' is a parenthetical phrase and does not make the subject plural; the subject is 'price', so the verb is singular: 'has'.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-328","question":"Improve the bracketed part: The manager, [as well as his assistants, were] summoned by the board.","options":["and his assistants, was","as well as his assistants was","as well as his assistants, was","No improvement"],"answer":2,"explanation":"With 'as well as', the verb agrees with the first subject 'manager', so 'was' is needed, and the parenthetical phrase is set off by commas. Replacing it with 'and' would make the subject plural.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-329","question":"The patient will not recover ___ he takes the medicine regularly for the full course.","options":["until","lest","if","unless"],"answer":3,"explanation":"'Will not recover unless he takes' means 'if he does not take'. 'Until' would imply recovery follows the taking of the medicine at some point, and 'lest' needs a fear clause with 'should'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-330","question":"He spoke softly lest he ___ the sleeping baby.","options":["wakes","woke","would wake","should wake"],"answer":3,"explanation":"'Lest' (meaning 'for fear that') is followed by 'should' + bare verb, or by the bare subjunctive. 'Would wake' and the indicative forms do not follow this pattern.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-331","question":"Improve the bracketed part: Nothing but the bare essentials [were packed] by the hikers.","options":["was packed","are packed","had packed","No improvement"],"answer":0,"explanation":"The subject is 'nothing', which is singular; 'but' here means 'except' and 'essentials' is not the subject. The verb should be 'was packed'.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-332","question":"Improve the bracketed part: Having lost his way in the dark, [the night was spent by the travellers] in a temple.","options":["the travellers spent the night","a night was spent by the travellers","the night the travellers spent","No improvement"],"answer":0,"explanation":"The participial phrase 'Having lost his way' must be followed by the person who lost it. In the original, 'the night' appears to have lost its way, which is a dangling modifier; 'the travellers spent the night' fixes it.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-333","question":"Improve the bracketed part: The proposal is [theoretical than practical].","options":["more theoretical","theoretical rather","more theoretically","No improvement"],"answer":0,"explanation":"When two qualities of the same thing are compared with 'than', both take the form 'more + adjective': 'more theoretical than practical'. 'Theoretical than' lacks the comparative marker.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-334","question":"Not a single member of the committee ___ in favour of the motion.","options":["are","was","were","have been"],"answer":1,"explanation":"'Not a single member' takes a singular verb, because the head word is 'member', not 'committee'. 'Were' is tempted by the plural noun 'members' implied by 'committee'.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-335","question":"Spot the error: The poor (a) / is often (b) / exploited by moneylenders. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"'The poor' (the + adjective) refers to a class of people and takes a plural verb. Part (b) should read 'are often'.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-336","question":"The accused pleaded not guilty ___ the charge of forgery.","options":["on","for","of","to"],"answer":3,"explanation":"One pleads guilty or not guilty 'to' a charge. 'Of' belongs to 'found guilty of', which is the common mix-up.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-337","question":"Choose the correct passive voice: Do you know him?","options":["Is he known to you?","Are you known to him?","Is he known by you?","Was he known to you?"],"answer":0,"explanation":"The verb 'know' takes 'to' in the passive ('known to'), and the present simple stays present. 'Known by' is used for a cause or agent, as in 'known by his deeds'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-338","question":"Choose the correct active voice: The fort is said to have been built by Akbar.","options":["People say that Akbar has built the fort.","People say that Akbar built the fort.","People said that Akbar builds the fort.","People say that Akbar is building the fort."],"answer":1,"explanation":"'Is said to have been built' means that people say the building happened in the past, so the active form is 'People say that Akbar built the fort'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-339","question":"Choose the correct indirect speech: He said, \"I shall come tomorrow.\"","options":["He said that I would come the next day.","He said that he should come the following day.","He said that he would come the next day.","He said that he will come tomorrow."],"answer":2,"explanation":"After a past reporting verb, 'shall' becomes 'would', 'I' becomes 'he', and 'tomorrow' becomes 'the next day'. The other options keep the present tense, change the person wrongly or alter the modal.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-340","question":"Choose the correct indirect speech: She said to me, \"Thank you for your help.\"","options":["She told me thanks for the help.","She said thanks to me for her help.","She thanked to me for my help.","She thanked me for my help."],"answer":3,"explanation":"A remark of thanks is reported with the verb 'thanked' + object, with 'your' becoming 'my'. 'Thank' takes no preposition before its object.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-341","question":"Choose the correct indirect speech: He said, \"Would that I were a king!\"","options":["He wished that he were a king.","He wished that he was a king.","He wished that he had been a king.","He said that would he be a king."],"answer":0,"explanation":"'Would that' expresses a wish, which is reported with 'wished', and the subjunctive 'were' is kept. Changing it to 'had been' would turn a present wish into a past regret.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-342","question":"I had no sooner reached the station ___ the train began to move.","options":["before","than","as","when"],"answer":1,"explanation":"'No sooner' is always paired with 'than'. 'When' goes with 'hardly' and 'scarcely'.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-343","question":"Spot the error: By the time you will reach (a) / the station, (b) / the train will have left. (c) / No error (d)","options":["a","b","c","d"],"answer":0,"explanation":"In a time clause beginning with 'By the time', the present simple is used for the future: 'By the time you reach'. 'Will' is not used after such conjunctions.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-344","question":"He ___ be over sixty, for he still plays football every day.","options":["must","ought to","cannot","should"],"answer":2,"explanation":"'Cannot' expresses a logical deduction that something is impossible, which suits the evidence that he still plays football daily. 'Must' would make the opposite deduction.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-345","question":"Spot the error: The news (a) / of the strikes (b) / were alarming. (c) / No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"'News' is singular in form and meaning, so it takes a singular verb: 'was alarming'. The plural 'strikes' in the 'of' phrase does not control the verb.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-346","question":"Spot the error: A friend of (a) / me (b) / came to see us yesterday. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"After 'a friend of', the double possessive is required: 'a friend of mine'. The objective 'me' in (b) is the error.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-347","question":"Spot the error: She not only sings (a) / well but also (b) / a good dancer. (c) / No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"'Not only ... but also' joins parts of the same kind, so after 'not only sings well' the second part must be a verb phrase: 'dances well'. The noun phrase 'a good dancer' breaks the parallelism.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-348","question":"Spot the error: The police (a) / has arrested (b) / two suspects. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"'Police' is always treated as a plural noun and takes a plural verb: 'have arrested'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-349","question":"Choose the option that correctly completes the sentence: Having been warned of the approaching storm, ___.","options":["the boats remained safe in the harbour","the boats were kept ashore by the fishermen","the storm did not trouble the fishermen","the fishermen kept their boats ashore"],"answer":3,"explanation":"The participial phrase 'Having been warned' must modify the person warned, who is the subject of the main clause. Only 'the fishermen kept their boats ashore' places the fishermen as subject; the others leave the modifier dangling.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-350","question":"The manager asked the two clerks to share the work ___.","options":["among each other","among themselves","with themselves","between themselves"],"answer":3,"explanation":"'Between' is used for two persons or things, and 'among' for three or more. 'With themselves' is not idiomatic for sharing.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-351","question":"Why don't you stop ___ and listen to what I am saying?","options":["talking","to talk","talk","to have talked"],"answer":0,"explanation":"'Stop + gerund' means to cease doing something, while 'stop + infinitive' means to pause in order to do something. The speaker wants him to cease talking, so 'talking' is right.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-352","question":"I clearly remember ___ the cheque to him, so it must have been lost in the post.","options":["having to give","to be given","to give","giving"],"answer":3,"explanation":"'Remember + gerund' refers to recalling an action already done, while 'remember + to-infinitive' means not forgetting to do something. The cheque was already handed over, so 'giving' fits.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-353","question":"Please remember ___ the lights before you leave the office tonight.","options":["to switch off","to switching off","switching off","switched off"],"answer":0,"explanation":"The action is still in the future, so 'remember' takes the to-infinitive ('to switch off'). The gerund would refer to an action already performed.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-354","question":"The new tax is likely to ___ the middle class most severely.","options":["effect","infect","affect","afflict"],"answer":2,"explanation":"'Affect' (verb) means to influence. 'Effect' as a verb means to bring about (effect a change), and 'infect' and 'afflict' do not fit a tax naturally.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-355","question":"The suspect's alibi was ___ by the CCTV footage from the shopping mall.","options":["corrugated","coordinated","collaborated","corroborated"],"answer":3,"explanation":"'Corroborated' means confirmed with supporting evidence. 'Collaborated' means worked together, 'corrugated' means ridged, and 'coordinated' means organised jointly.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-356","question":"I need ___ information before I can decide whether to approve the loan.","options":["further","farthest","farther","furthest"],"answer":0,"explanation":"'Further' means additional, while 'farther' refers only to physical distance. 'Furthest' and 'farthest' are superlatives and do not fit.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-357","question":"Spot the error: He divided the sweets (a) / between the ten children (b) / of the orphanage. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"'Between' is used for two, and 'among' for more than two. Part (b) should read 'among the ten children'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-358","question":"Spot the error: He did not (a) / find the book (b) / neither the pen. (c) / No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"'Did not' already makes the sentence negative, so 'neither' creates a double negative. Part (c) should read 'or the pen'.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-359","question":"Improve the bracketed part: The annual meeting will be [held on the second week of] March.","options":["held at the second week of","held in the second week of","held during in the second week of","No improvement"],"answer":1,"explanation":"A week within a month takes 'in' ('in the second week of March'). 'On' is used with a particular day or date.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-360","question":"He is senior ___ me in service, but I am older ___ him in age.","options":["than; to","to; to","to; than","than; than"],"answer":2,"explanation":"'Senior', 'junior', 'superior' and 'inferior' take 'to', while the comparative 'older' takes 'than'. So the pair is 'to; than'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-361","question":"Improve the bracketed part: He did not know [where was the station].","options":["where the station was","where the station is it","where was the station located","No improvement"],"answer":0,"explanation":"After 'know', an embedded question takes statement word order (subject before verb): 'where the station was'. Inversion is kept only in direct questions.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-362","question":"Improve the bracketed part: She has [less than ten friends] in the city.","options":["lesser than ten friends","fewer than ten friends","few than ten friends","No improvement"],"answer":1,"explanation":"'Friends' is countable, so 'fewer' is required; 'less' is for uncountable quantities. 'Lesser' and 'few than' are not standard.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-363","question":"Improve the bracketed part: I [am knowing] the family for over twenty years.","options":["have been knowing","have known","know since","No improvement"],"answer":1,"explanation":"'Know' is a stative verb and is not used in continuous tenses, and 'for twenty years' needs a perfect tense: 'have known'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-364","question":"Improve the bracketed part: Of the two plans, this is [the best].","options":["better","most good","the better","No improvement"],"answer":2,"explanation":"For a choice between two, the comparative with 'the' is used: 'the better'. The superlative 'the best' is for three or more.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-365","question":"I am late again, ___?","options":["isn't it","am I not","amn't I","aren't I"],"answer":3,"explanation":"The standard tag for 'I am' is 'aren't I'. 'Amn't I' is dialect, and 'am I not' is stiff and non-standard in a tag.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-366","question":"Let's take a short break now, ___?","options":["shall we","will you","don't we","let us"],"answer":0,"explanation":"A suggestion beginning with 'Let's' takes the tag 'shall we?'. 'Will you' is the tag for ordinary imperatives.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-367","question":"He is ___ honest man that everyone trusts him with their savings.","options":["such","such an","so","so an"],"answer":1,"explanation":"Before 'a/an + adjective + noun' the intensifier is 'such' ('such an honest man'). 'So' is used directly before an adjective, without the article and noun.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eng-grammar-368","question":"The ___ of the matter is that no one is willing to take responsibility.","options":["crush","crust","crux","crutch"],"answer":2,"explanation":"'Crux' means the central, decisive point of a problem. 'Crust' is an outer layer, 'crutch' is a support for walking, and 'crush' means to squash.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-369","question":"Spot the error: It was (a) / him who broke (b) / the window. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"After 'it was' in a cleft sentence, the formal pronoun is in the subjective case, since it is the subject of 'broke': 'It was he who broke'. So (b) is wrong.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-370","question":"Spot the error: The cost of (a) / these textbooks (b) / are very high. (c) / No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"The subject is 'cost' (singular), not 'textbooks'. Part (c) should read 'is very high'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-371","question":"Choose the correct passive voice: They are building a new bridge across the river.","options":["A new bridge is being build across the river.","A new bridge is built across the river by them.","A new bridge has been building across the river.","A new bridge is being built across the river."],"answer":3,"explanation":"The present continuous active 'are building' becomes 'is being built' in the passive. The other options use the wrong tense or an incorrect verb form.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-372","question":"Choose the correct indirect speech: The doctor said to him, \"Take complete rest for a week.\"","options":["The doctor advised him to take complete rest for a week.","The doctor said him to take complete rest for a week.","The doctor told that he should take rest for a week.","The doctor advised him that take complete rest for a week."],"answer":0,"explanation":"An imperative is reported with a verb of advice or order followed by an object and 'to' + infinitive. 'Said' cannot take an object like that, and 'that' with a bare verb is ungrammatical.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-grammar-373","question":"This is the house ___ my grandfather was born.","options":["that","where","whom","which"],"answer":1,"explanation":"The relative word refers to a place and the clause is complete without it ('my grandfather was born in the house'), so 'where' is used. 'Which' or 'that' would need 'in which' to be correct.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-374","question":"Which of the following words is spelt correctly, as it would be in a formal official report?","options":["Conscientious","Consciencious","Conscienscious","Concientious"],"answer":0,"explanation":"The word is built from 'conscience' + '-tious': c-o-n-s-c-i-e-n-t-i-o-u-s. The other forms drop the 'c' of 'sc' or the 't'.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-375","question":"Select the option in which the word meaning 'to make someone feel awkward or ashamed in public' is correctly spelt.","options":["Embaress","Embarrass","Embarrasse","Embarass"],"answer":1,"explanation":"'Embarrass' has a double r and a double s: em-bar-rass. Most wrong spellings drop one of the doubled letters.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
];

export default questions;
